export const SEARCH_INDEX: SearchEntry[] = [{"slug":"account_and_routes","title":"Account, routes & story ownership","folder":"","heading":"Account, routes & story ownership","id":"","text":""},{"slug":"account_and_routes","title":"Account, routes & story ownership","folder":"","heading":"Account, routes & story ownership","id":"","text":""},{"slug":"account_and_routes","title":"Account, routes & story ownership","folder":"","heading":"Routes (lib/routes.ts is the single source of truth)","id":"routes-libroutests-is-the-single-source-of-truth","text":"URL Page / Search landing (or the story page if a story is loaded) /story/[id] A story's own page — refresh-safe and shareable; story cards link here /dashboard, /profile/[userId] Home dashboard, public profile /reading-history Every story read, grouped by date, paginated /analytics Speed / comprehension charts /history Past test attempts (also in the hamburger menu) /settings Theme, reading font, reading speed Navbar: the reading-mode toggle and the story-title link were removed; the profile menu rows are real routes."},{"slug":"account_and_routes","title":"Account, routes & story ownership","folder":"","heading":"Story ownership","id":"story-ownership","text":"An uploaded story belongs to the user whose personal library holds it. SessionManager.findCustomStoryOwner(id) finds that user; getContentAuthorId asks it first (via registerCustomStoryOwnerResolver, wired in lib/session/composition.ts) and only falls back to the demo mapping for built-in stories. The resolver is injected so contentMeta never imports the session layer (which depends on the store that imports contentMeta — a cycle otherwise). Test: npm test."},{"slug":"account_and_routes","title":"Account, routes & story ownership","folder":"","heading":"Profile photo","id":"profile-photo","text":"lib/avatar.ts centre-crops to 256px JPEG; devDataStore.setAvatar/getAvatar persist it (own photo only). components/ui/Avatar.tsx shows photo → initial → icon; used in the navbar, profile menu and profile page. Upload/remove: profile menu or profile page (useAvatarUpload)."},{"slug":"account_and_routes","title":"Account, routes & story ownership","folder":"","heading":"Edit story","id":"edit-story","text":"EditStoryModal reuses the Add-story modal parts (StoryFormParts, StoryCoverPicker, QuestionsInput, rich editor) so both look identical. Replaced/removed cover videos are deleted only when the edit is saved."},{"slug":"account_and_routes","title":"Account, routes & story ownership","folder":"","heading":"Navbar layout & audience section","id":"navbar-layout-audience-section","text":"Navbar: left hamburger menu company name; right notifications, dark-mode switch (ThemeSwitch), profile. The centre slot still hosts the search box / reading timer. Landing \"For every ambitious mind.\" is an Apple-style carousel (components/Landing/AudienceMarquee.tsx): tall dark cards, caption below with a bold lead, previous/next buttons bottom-right, scroll-snap and touch swipe."},{"slug":"account_and_routes","title":"Account, routes & story ownership","folder":"","heading":"Profile button, logout, carousel","id":"profile-button-logout-carousel","text":"The navbar profile button opens your profile page directly (no dropdown). Dashboard / Reading history / Analytics / Past test attempts / Settings are quick links on your own profile page; Log out is at the bottom of the hamburger menu. Landing story carousel: translucent glass covers sit outside the two vertical guide lines (under the arrows); each card's arrow button starts auto-scroll reading at /reader (StoryCard arrowStartsReader), everything else on the card is unchanged."},{"slug":"deployment","title":"Deployment","folder":"","heading":"Deployment","id":"","text":""},{"slug":"deployment","title":"Deployment","folder":"","heading":"Deployment","id":"","text":""},{"slug":"deployment","title":"Deployment","folder":"","heading":"Requirements","id":"requirements","text":"Node.js 18.17 (20 recommended, see .nvmrc), npm 9."},{"slug":"deployment","title":"Deployment","folder":"","heading":"Environment","id":"environment","text":"Variable When Purpose NEXTPUBLICAPIURL build time Backend base URL incl. /api/v1. Empty standalone frontend. See .env.production.example. NEXTPUBLIC values are baked into the bundle, so change them → rebuild."},{"slug":"deployment","title":"Deployment","folder":"","heading":"Build and run (any Linux server)","id":"build-and-run-any-linux-server","text":"npm ci npm run typecheck && npm test # gates npm run build npm start # serves on :3000 (PORT… to change), binds 0.0.0.0 Keep it alive with systemd or PM2 (pm2 start npm --name speed-reader -- start) behind nginx/Caddy that terminates TLS and proxies to 127.0.0.1:3000."},{"slug":"deployment","title":"Deployment","folder":"","heading":"Docker","id":"docker","text":"docker build -t speed-reader --build-arg NEXTPUBLICAPIURLhttps://api.example.com/api/v1 . docker run -d -p 3000:3000 --restart unless-stopped speed-reader Multi-stage, non-root, with a healthcheck."},{"slug":"deployment","title":"Deployment","folder":"","heading":"nginx (example)","id":"nginx-example","text":"server { listen 443 ssl http2; servername app.example.com; location / { proxypass http://127.0.0.1:3000; proxysetheader Host $host; proxysetheader X-Forwarded-For $remoteaddr; proxysetheader X-Forwarded-Proto $scheme; } }"},{"slug":"deployment","title":"Deployment","folder":"","heading":"Landing video","id":"landing-video","text":"Put your file at public/videos/landing-hero.mp4 (optional .webm landing-hero-poster.jpg). Served with a long-lived cache header; rename the file when you replace it so browsers refetch."},{"slug":"deployment","title":"Deployment","folder":"","heading":"Conventions that keep the build green","id":"conventions-that-keep-the-build-green","text":"CSS: plain .css files are imported only in app/layout.tsx (Next.js rejects global CSS imported from components). New component styles: use Tailwind, or a Name.module.css imported by the component. Browser-only reads (localStorage, window) happen in useEffect, never during render, to avoid hydration mismatches. Hook/browser files start with \"use client\". Lint runs in CI (npm run lint), not during next build."},{"slug":"deployment","title":"Deployment","folder":"","heading":"Smoke test after deploy","id":"smoke-test-after-deploy","text":"/ (hero, carousel, sections) · /dashboard · open a story → /reader · reading mode → /read · sign-in · theme switch · 404 page (/nope)."},{"slug":"deployment","title":"Deployment","folder":"","heading":"Security headers","id":"security-headers","text":"Set in next.config.js (nosniff, frame options, referrer policy, permissions policy with microphone allowed for voice search). Add HSTS at the proxy once HTTPS is final."},{"slug":"deployment","title":"Deployment","folder":"","heading":"PDF support (pdf.js)","id":"pdf-support-pdfjs","text":"next build fails with \"failed to parse input file / Syntax Error\" if pdf.js's modern build or worker goes through the SWC minifier. So: the app imports pdfjs-dist/legacy/build/pdf.mjs (pinned to 4.4.168) and loads the worker from /pdf.worker.min.mjs, which scripts/copy-pdf-worker.mjs copies into public/ automatically before npm run dev and npm run build. After upgrading pdfjs-dist, just rebuild."},{"slug":"deployment","title":"Deployment","folder":"","heading":"Troubleshooting","id":"troubleshooting","text":"Cannot find module '.next/server/middleware-manifest.json' and every page is a 500: a stale .next folder (usually left by a failed npm run build) is being reused by next dev. npm run dev now clears it automatically; manually: stop the server, rm -rf .next, start again. Use Node 20 LTS (nvm use), and keep the project in a folder path without spaces or brackets (not speed-reader-frontend (3)); both avoid odd dev-server failures."},{"slug":"deployment","title":"Deployment","folder":"","heading":"Browser storage used by the app","id":"browser-storage-used-by-the-app","text":"localStorage (stories, history, per-user sessions, theme settings), IndexedDB speed-reader-media (story hover videos) and speed-reader-backgrounds (landing theme uploads). Nothing is sent to a server unless NEXTPUBLICAPIURL is set."},{"slug":"landing_themes","title":"Landing-page themes (\"Add theme\")","folder":"","heading":"Landing-page themes (\"Add theme\")","id":"","text":""},{"slug":"landing_themes","title":"Landing-page themes (\"Add theme\")","folder":"","heading":"Landing-page themes (\"Add theme\")","id":"","text":"Open the hamburger menu → Add theme. It changes the background of the landing page hero only; nothing else in the app. Theme What it is Dots (default) The twinkling dot grid (no mouse interaction). Grainient Animated-free WebGL gradient from components/ui/Grainient.tsx, configured in components/Landing/LandingBackground.tsx. Your uploads Any photo (PNG/JPEG/WebP/GIF/AVIF, ≤ 25 MB) or video (MP4/WebM/MOV, ≤ 80 MB). Videos play muted and looping. Hover a tile to delete it. Adjustments (apply to every theme): Contrast 0.5–1.5, Brightness 0.4–1.6, Saturation 0–2, Dim 0–0.8 (black scrim for text legibility). \"Reset adjustments\" restores neutral values."},{"slug":"landing_themes","title":"Landing-page themes (\"Add theme\")","folder":"","heading":"Where things live","id":"where-things-live","text":"lib/landingTheme.ts – selected theme adjustments, saved in localStorage (speed-reader.landing-theme.v1); useLandingTheme() keeps the menu and the landing page in sync. lib/landingMedia.ts – uploaded files, stored in IndexedDB (speed-reader-backgrounds). components/Navigation/ThemePanel.tsx – the menu UI. components/Search/SearchLanding.tsx – renders the chosen background. \"Reset everything\" in the menu also clears the saved theme and uploads."},{"slug":"landing_themes","title":"Landing-page themes (\"Add theme\")","folder":"","heading":"Notes","id":"notes","text":"Grainient needs WebGL2; without it the hero simply shows the page background. Defaults leave the original dot background untouched (no filter is applied at neutral values). The Grainient theme is dark by design; on the light site theme use Brightness/Dim to keep the headline readable."},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"OOP Architecture & Per-User Sessions","id":"","text":""},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"OOP Architecture & Per-User Sessions","id":"","text":"This document explains how user data is isolated per user, which object-oriented principles and patterns are used, why, and exactly where. Every class and file named here exists in the repo; nothing is described that isn't implemented. 1. What changed and why 2. What \"a session\" contains (feature → class → screen) 3. Class diagram 4. How a user switch flows through the system 5. OOP principles — what, why, where 6. SOLID — one by one 7. Design patterns used 8. Where OOP is deliberately not used 9. Storage layout, migration and the guest session 10. Design decisions and trade-offs 11. How to add a new per-user feature 12. Testing 13. Known limitations and next steps"},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"1. What changed and why","id":"1-what-changed-and-why","text":"Before: every persisted feature wrote to one global, un-namespaced localStorage key (srt:history, srt:daily, srt:streak, …). Anyone who logged in on the same browser saw and changed the same history, calendar, streaks, pace graphs, bookmarks and uploads. Backend login tokens were browser-wide too, so user B's reading sessions could be synced into user A's backend account. Now: every signed-in user has their own isolated UserSession — a bundle of repositories that can only read and write that user's data. Switching user switches the session and remounts the React tree, so no screen or in-memory state leaks across users. Requirements this satisfies: Requirement How Separate session per user for graphs, consistency/streak calendar, pace, etc. DailyActivityRepository, StreakRepository, HistoryRepository are constructed per user (§2) \"Everything\" separate, not just some features Bookmarks, achievements, uploads, search history, backend tokens, and the reader's in-memory state are all per-user too Proper OOP Abstract base hierarchy, encapsulated repositories, interfaces, composition, DI (§5–§7) Documented This file"},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"2. What \"a session\" contains","id":"2-what-a-session-contains","text":"One UserSession (lib/session/UserSession.ts) composes one repository per feature. Each repository owns exactly one slot in the user's storage namespace. Feature Class Storage slot (srt:v2:u:<userId>:…) Screens that read/write it Reading quiz history, quiz stats HistoryRepository history /history (Past test attempts), /results, reader completion Daily activity — feeds the contribution/streak calendar, the daily pace (WPM) chart, the efficiency/break trends, dashboard totals DailyActivityRepository daily ContributionHeatmap, DailyTrendChart, EfficiencyTrends, Dashboard, useBreakTracker Streak counter StreakRepository streak Landing page, reader completion Lifetime stats (current/longest streak, averages, efficiency) LifetimeStatsCalculator (pure, via UserSession.lifetimeStats()) — (derived from daily) Dashboard, ContributionHeatmap header Bookmarks BookmarkRepository bookmarks Landing page Achievements AchievementRepository achievements — Uploaded / custom stories CustomStoryRepository customStories Library, search, AddStoryModal, EditStoryModal, \"Clear all uploaded stories\" Search history SearchHistoryRepository searchHistory SearchBar, HamburgerMenu Backend (JWT) tokens ScopedTokenStore apiAccessToken, apiRefreshToken lib/api/, AuthProvider, notification stream Reader state (current story, phase, answers, fonts) React tree remount via SessionBoundary in memory everything under the reader Social data (follows, likes, comments, shares, notifications, playlists) already lived in lib/devData/store.ts as records keyed by userId, so it was per-user by construction and is unchanged."},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"3. Class diagram","id":"3-class-diagram","text":"classDiagram direction LR class KeyValueStore { <<interface>> getItem(key) string null setItem(key, value) void removeItem(key) void keys() string[] } class BrowserKeyValueStore class MemoryKeyValueStore KeyValueStore < .. BrowserKeyValueStore KeyValueStore < .. MemoryKeyValueStore class UserNamespace { <<value object>> userId key(feature) string owns(key) bool parse(key)$ forUser(id)$ UserNamespace } class UserScopedRepositoryT { <<abstract>> #feature() string #emptyValue() T #deserialize(raw) T #read() T #write(value) void clear() void } class ListRepositoryTItem { <<abstract>> getAll() TItem[] #mutate(fn) TItem[] } UserScopedRepository < -- ListRepository UserScopedRepository < -- StreakRepository UserScopedRepository < -- DailyActivityRepository ListRepository < -- HistoryRepository ListRepository < -- BookmarkRepository ListRepository < -- AchievementRepository ListRepository < -- CustomStoryRepository ListRepository < -- SearchHistoryRepository UserScopedRepository o-- KeyValueStore : injected UserScopedRepository o-- UserNamespace : injected class DailyActivityEntry { <<immutable entity>> merge(input) DailyActivityEntry } class LifetimeStatsCalculator { compute(daily, now) LifetimeStats } DailyActivityRepository ..> DailyActivityEntry : uses class UserSession { <<aggregate / facade>> history streak daily bookmarks achievements customStories searchHistory lifetimeStats() clearAllData() } UserSession -- HistoryRepository UserSession -- StreakRepository UserSession -- DailyActivityRepository UserSession -- BookmarkRepository UserSession -- AchievementRepository UserSession -- CustomStoryRepository UserSession -- SearchHistoryRepository UserSession o-- LifetimeStatsCalculator class IdentityProvider { <<interface>> currentUserId() string null subscribe(listener) unsubscribe } class DevStoreIdentityProvider IdentityProvider < .. DevStoreIdentityProvider class SessionManager { <<registry observer>> active() UserSession sessionFor(userId) UserSession activeUserId() string subscribe(listener) getVersion() number findCustomStoryAnywhere(id) } SessionManager o-- IdentityProvider : injected SessionManager o-- KeyValueStore : injected SessionManager o-- LegacyDataMigrator SessionManager \"1\" o-- \"\" UserSession : one per user id class ScopedTokenStore ScopedTokenStore o-- KeyValueStore : injected File map: lib/session/ storage/KeyValueStore.ts KeyValueStore, BrowserKeyValueStore, MemoryKeyValueStore, factory UserNamespace.ts key scheme (value object) UserScopedRepository.ts UserScopedRepository (abstract) ListRepository (abstract) repositories/.ts History, Streak, DailyActivity, Bookmark, Achievement, CustomStory, SearchHistory analytics/DailyActivityEntry.ts one day's aggregate (immutable) analytics/LifetimeStatsCalculator.ts streak average math (stateless) UserSession.ts aggregate of all repositories for one user SessionManager.ts active-user resolution, session cache, change notification LegacyDataMigrator.ts one-time move of pre-session global data identity/IdentityProvider.ts interface: who is signed in? identity/DevStoreIdentityProvider.ts adapter over the dev login composition.ts composition root (the only place concrete classes are wired) useUserSession.ts React bindings (useSyncExternalStore) lib/api/ScopedTokenStore.ts per-user backend tokens lib/storage.ts facade: old storage. API → active user's session components/Session/SessionBoundary.tsx remounts the tree on user change"},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"4. How a user switch flows through the system","id":"4-how-a-user-switch-flows-through-the-system","text":"Login / logout (DevLoginGate → devDataStore.login / logout) │ devDataStore notifies its subscribers ▼ DevStoreIdentityProvider.subscribe ──► SessionManager.onIdentityMaybeChanged() │ compares resolved user id with the last one; │ unrelated store noise (a like, a comment) is ignored ▼ SessionManager.version → notifies subscribers ▼ useActiveUserId() (useSyncExternalStore) → SessionBoundary re-renders ▼ <Fragment key{userId}> → React unmounts & remounts the whole subtree ▼ Every component re-runs its effects → storage. / sessionManager.active() ▼ Resolves the NEW user's UserSession (created once, then cached) Two things make this robust: 1. Resolution at call time. storage.getHistory() calls sessionManager.active() each time; nothing captures \"the current user\" at import. A stale reference to the wrong user's repositories cannot exist. 2. Remount, not just re-read. Persisted data is isolated by the session layer, but React state (the reader's current story, answers, cached useState reads) would otherwise survive a switch. Keying a Fragment by user id resets all of it. Same user ⇒ same key ⇒ no remount, so ordinary navigation is unaffected."},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"5. OOP principles — what, why, where","id":"5-oop-principles-what-why-where","text":""},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"5.1 Encapsulation","id":"51-encapsulation","text":"Hide state and representation behind a small, intention-revealing public API. Where What is hidden Public surface UserScopedRepository storage key, JSON parsing, defensive fallbacks (read/write/storageKey are protected) clear() each subclass's verbs HistoryRepository the 50-entry cap and newest-first ordering add, update, quizAttempts, quizStats StreakRepository that count last-read date are stored as one record (they can't be written out of step) get, bump BrowserKeyValueStore window may not exist (SSR), access may throw (private mode), quota errors the 4 KeyValueStore methods that never throw UserNamespace the key format (srt:v2:u:<id>:<feature>) and URL-encoding of ids key(), owns(), parse() DailyActivityEntry the 12 raw counters and how a session folds into them merge(), toJSON() ScopedTokenStore namespaced keys, guest adoption, legacy-key migration get/set/clear token methods UserSession that repositories are constructed with this namespace (readonly fields, no setters) repository properties Why: callers can't produce a wrong key, skip the cap, or mutate a half-built record. The isolation guarantee is structural — no call site has to \"remember\" to include the user id. export abstract class UserScopedRepository<T> { constructor( protected readonly store: KeyValueStore, protected readonly namespace: UserNamespace ) {} protected storageKey(): string { return this.namespace.key(this.feature()); } protected read(): T { const raw this.store.getItem(this.storageKey()); if (raw null) return this.emptyValue(); try { return this.deserialize(JSON.parse(raw)); } catch { return this.emptyValue(); } } }"},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"5.2 Abstraction","id":"52-abstraction","text":"Program against what something does, not how. KeyValueStore abstracts \"where bytes live\" (browser, memory, later IndexedDB/API). IdentityProvider abstracts \"who is signed in\" (dev login now, backend JWT later). UserScopedRepository<T> abstracts \"a persisted per-user value\" — UserSession.clearAllData() clears seven different repositories through this one type without knowing which is which. Why: the session layer has no knowledge of localStorage or of the dev login, so either can be replaced without touching a single repository. export interface KeyValueStore { getItem(key: string): string null; setItem(key: string, value: string): void; removeItem(key: string): void; keys(): string[]; }"},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"5.3 Inheritance (used sparingly, two levels)","id":"53-inheritance-used-sparingly-two-levels","text":"Reuse an invariant algorithm; specialise only what varies. UserScopedRepository<T> read / write / clear / key building (abstract) ├─ StreakRepository object value ├─ DailyActivityRepository map value └─ ListRepository<TItem> array value: getAll / mutate (abstract) ├─ HistoryRepository cap 50, update-in-place, quiz stats ├─ BookmarkRepository toggle ├─ AchievementRepository idempotent unlock ├─ CustomStoryRepository upsert by id, ownership check └─ SearchHistoryRepository cap 30, case-insensitive de-dupe Why inheritance here: seven repositories share one real \"is-a\" relationship and one algorithm. ListRepository exists because five of them are lists and would otherwise each re-write the empty-array default, the \"is it really an array?\" guard and read-modify-write. The hierarchy stops at two levels on purpose — deeper trees get brittle. export class SearchHistoryRepository extends ListRepository<SearchHistoryEntry> { static readonly MAXENTRIES 30; protected feature(): string { return \"searchHistory\"; } protected deserialize(raw: unknown): SearchHistoryEntry[] { if (!Array.isArray(raw)) return []; const now new Date().toISOString(); return raw.map((entry) > (typeof entry \"string\" ? { term: entry, date: now } : (entry as SearchHistoryEntry))); } }"},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"5.4 Polymorphism","id":"54-polymorphism","text":"One call, different behavior depending on the concrete type. Template Method hooks. The base class's read() calls this.deserialize(...) and this.emptyValue(). SearchHistoryRepository overrides deserialize to upgrade the older string[] shape; StreakRepository overrides it to validate an object; the base flow never changes. Interface polymorphism. BrowserKeyValueStore and MemoryKeyValueStore are interchangeable behind KeyValueStore (the tests use the memory one in place of localStorage). Uniform treatment. UserSession.clearAllData() loops ReadonlyArray<UserScopedRepository<unknown>> and calls clear() on each. private readonly repositories: ReadonlyArray<UserScopedRepository<unknown>>; / Wipes every feature's data for this user only. / clearAllData(): void { this.repositories.forEach((repo) > repo.clear()); }"},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"5.5 Composition over inheritance","id":"55-composition-over-inheritance","text":"Build big things by combining small collaborators. UserSession has seven repositories and a LifetimeStatsCalculator — it doesn't inherit from them. DailyActivityRepository uses DailyActivityEntry for the merge rule instead of embedding it. SessionManager has a store, an identity provider and a migrator, all injected. Why: \"a user's session\" isn't a kind of repository; it's a bundle of them. Composition keeps each piece independently testable and replaceable. constructor( readonly namespace: UserNamespace, store: KeyValueStore, private readonly stats: LifetimeStatsCalculator new LifetimeStatsCalculator() ) { this.history new HistoryRepository(store, namespace); // …one repository per feature, same namespace }"},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"5.6 Immutability / value objects","id":"56-immutability-value-objects","text":"UserNamespace and DailyActivityEntry never change after construction (merge returns a new entry). Why: a half-applied update can't be observed or saved, and equal namespaces are interchangeable. export class UserNamespace { static readonly GUESTID \"guest\"; private constructor(readonly userId: string) {} static forUser(userId: string null undefined): UserNamespace { const trimmed userId?.trim(); return new UserNamespace(trimmed ? trimmed : UserNamespace.GUESTID); } }"},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"6. SOLID — one by one","id":"6-solid-one-by-one","text":"Principle Where it shows up Single Responsibility LifetimeStatsCalculator only computes (no storage); repositories only persist (no stat math); SessionManager only resolves/caches/notifies; LegacyDataMigrator only migrates; UserNamespace only knows the key scheme. Open/Closed New per-user feature new subclass one registration in UserSession (§11). No existing repository is edited. A new store or identity source new class implementing an interface. Liskov Substitution Any KeyValueStore works anywhere one is expected; any ListRepository subclass honours getAll()/mutate(); MemoryKeyValueStore is a drop-in for the browser store (proved by the test suite running with no browser). Interface Segregation KeyValueStore is 4 methods; IdentityProvider is 2; DevIdentitySource (what the adapter needs from the dev store) is 2. Nothing is forced to depend on methods it doesn't use. Dependency Inversion Repositories depend on KeyValueStore UserNamespace, not on localStorage. SessionManager depends on IdentityProvider, not on the dev store. Concrete classes are chosen in exactly one place: composition.ts."},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"7. Design patterns used","id":"7-design-patterns-used","text":"Pattern Class / file Purpose Repository all Repository classes One object per feature owns reading/writing that data; UI never touches storage. Template Method UserScopedRepository (feature, emptyValue, deserialize, serialize hooks) Fixed read/write algorithm, varying steps in subclasses. Facade UserSession; lib/storage.ts UserSession gives one entry point to seven repositories. storage. keeps the old API so the 34 existing call sites became per-user with zero edits. Aggregate / Composition Root UserSession; composition.ts One consistent unit per user; one place that wires concrete classes. Observer SessionManager.subscribe/getVersion ( useSyncExternalStore) React re-renders when the active user changes. Same shape as devDataStore. Registry / Flyweight-style cache SessionManager.sessions (Map<userId, UserSession>) Exactly one session object per user, created lazily and reused. Adapter DevStoreIdentityProvider Presents the dev login as an IdentityProvider; a future ApiIdentityProvider slots in beside it. Factory createDefaultKeyValueStore() Picks browser vs memory store for the runtime (SSR-safe). Value Object UserNamespace, DailyActivityEntry Immutable, compared by value. Singleton (by module scope) sessionManager, tokenStore One instance per page. Created in composition.ts/tokenStore.ts, injected with its dependencies — so classes stay testable (tests build their own instances)."},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"8. Where OOP is deliberately not used","id":"8-where-oop-is-deliberately-not-used","text":"Honest scope, so nothing here is overstated: React components and hooks stay function components. Class components are deprecated in modern React and fight hooks/Server Components. OOP is applied to the domain and data layer underneath them — which is where stateful logic and invariants live. (DevDataStore in lib/devData/store.ts was already a class with the Observer pattern; it's unchanged.) ReadingContext is a reducer. A finite-state machine (useReducer) is the right model for the reading-flow transitions; wrapping it in classes would add ceremony, not clarity. The backend (speed-reader-backend) was not refactored in this change. Its user-owned data is already per-user at the database level: reading history and stats (where: { userId }), notifications (by recipientId), playlists (ownership-checked), and refresh-token sessions (a RefreshToken table with revokedAt, rotated on use, with reuse detection). Public content — stories and feeds — is intentionally shared across users. It already uses OOP where it matters: the AppError hierarchy (NotFoundError, UnauthorizedError, ForbiddenError, ConflictError, ValidationError) is classic inheritance polymorphism, consumed by the central error handler. Its services are module-level functions. Converting them to classes with a constructor-injected Prisma client is the natural next step (§13), but I could not type-check backend changes in the environment this was built in (npm registry unreachable, so no Express/Prisma types), and I would rather not ship an unverified refactor of auth/data code."},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"9. Storage layout, migration and the guest session","id":"9-storage-layout-migration-and-the-guest-session","text":""},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"Key scheme","id":"key-scheme","text":"srt:v2:u:<encodeURIComponent(userId)>:<feature> srt:v2:u:user-1:history srt:v2:u:user-1:daily srt:v2:u:user-2:history ← a different key by construction; collisions are impossible UserNamespace.parse(key) is the inverse, used to discover other users' namespaces."},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"Legacy data (no data loss)","id":"legacy-data-no-data-loss","text":"Old builds wrote global keys (srt:history, srt:daily, …). LegacyDataMigrator: 1. Runs when a non-guest user's session is first created. 2. Copies each legacy key into that user's namespace (the two-key streak becomes one record), never overwriting data the user already has. 3. Deletes the legacy keys and writes srt:v2:legacy-claimed-by <userId>. 4. So the first real user to sign in after the update inherits the old data, and no second user can."},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"Guest session","id":"guest-session","text":"When nobody is signed in, the active namespace is guest. It never claims legacy data. (In practice the app shows the login gate, so nothing is persisted as guest — except a backend login made on the login screen, which is adopted by the next user, see below.)"},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"Backend tokens","id":"backend-tokens","text":"ScopedTokenStore keeps each user's JWT pair in their own namespace. The login screen allows connecting a backend account before choosing a demo persona, so those tokens land in the guest slot; the first real user who reads tokens with none of their own adopts them (moved, not copied). Pre-session browser-wide tokens are adopted the same way. AuthProvider sits inside SessionBoundary so it re-restores the backend login for each user."},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"10. Design decisions and trade-offs","id":"10-design-decisions-and-trade-offs","text":"Logical isolation, not a security boundary. All of it lives in the same browser's localStorage; anyone with dev-tools can read any namespace. This stops accidental mixing between users and gives each user a clean, consistent experience. The real security boundary is the backend (JWT where: { userId }). Uploads are per-user; shared stories still open. Each user's uploaded stories live only in their own library, search and feed. But a notification only carries a content id, so getStoryById() falls back to a read-only lookup across users (SessionManager.findCustomStoryAnywhere) so a story someone shared with you can open. That grants no ownership — edit/delete buttons use isCustomStory(), which checks only the active user's own uploads. Facade over rewrite. Keeping storage. unchanged made the isolation change zero-risk for every screen. New code should use useUserSession() / the repositories directly. Lazy session resolution. sessionManager.active() is resolved per call, not captured, so a stale session can't be used after a switch. Remount on switch. Slightly more work than re-reading, but it is the only way to guarantee no in-memory state (current story, quiz answers, cached reads) leaks between users. Limited inheritance depth. Two levels, justified by a true shared algorithm; everything else is composition."},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"11. How to add a new per-user feature","id":"11-how-to-add-a-new-per-user-feature","text":"Example: remembering each user's last-used reading speed. // lib/session/repositories/PreferenceRepository.ts import { UserScopedRepository } from \"@/lib/session/UserScopedRepository\"; export class PreferenceRepository extends UserScopedRepository<{ wpm: number }> { protected feature() { return \"preferences\"; } protected emptyValue() { return { wpm: 250 }; } getWpm() { return this.read().wpm; } setWpm(wpm: number) { this.write({ wpm }); } } Then register it in UserSession: readonly preferences: PreferenceRepository; // constructor: this.preferences new PreferenceRepository(store, namespace); // and add this.preferences to the repositories array so clearAllData() covers it. That's the whole change — isolation, caching, user switching and tests-by-substitution come free. Use it from React with const { preferences } useUserSession();."},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"12. Testing","id":"12-testing","text":"npx tsx scripts/session-isolation.test.ts # or: npm run test:session Runs under plain Node (no browser, no framework) because the layer depends only on interfaces (MemoryKeyValueStore a fake IdentityProvider). 21 tests, covering: history, quiz attempts/stats, daily activity (calendar/pace/efficiency source), streaks, bookmarks, achievements, search history and uploads never cross users caps (50 history / 30 searches), update-in-place, idempotent unlock, case-insensitive search de-dupe streak rules (same day / next day / gap) and lifetime-streak math incl. the \"today not yet read\" grace clear() / clearAllData() affect only one user old string[] search history is upgraded; corrupt JSON degrades to empty, never throws namespace keys round-trip, even for ids containing : / %; no prefix collisions user switching, session caching, version bumps only on real user change (not on unrelated store noise) data survives sign-out/sign-in and a simulated reload shared-story lookup is read-only; ownership stays per user legacy migration: first real user claims once, guest never claims, never overwrites backend tokens: per-user, guest-login adopted by exactly one user, legacy tokens adopted once Additionally, a one-off differential test compared the new LifetimeStatsCalculator DailyActivityRepository against the original storage.ts on 300 randomized histories — all outputs identical, so the refactor changed where data lives, not what the numbers are. The session layer and the changed API files also pass tsc --strict."},{"slug":"oop_architecture","title":"OOP Architecture & Per-User Sessions","folder":"","heading":"13. Known limitations and next steps","id":"13-known-limitations-and-next-steps","text":"1. Backend class-based refactor (not done — see §8). Plan: one class per module (HistoryService, PlaylistService, …) taking PrismaClient (and Redis/S3 where needed) in the constructor; controllers as classes receiving the service; a small composition root replacing the module-level import { prisma }. Do it where npm run build can verify it. 2. Social store remains one shared in-browser store. DevDataStore is a single class holding records for all 20 demo users (keyed by userId), which is what the social features need. When the real backend takes over, it is replaced, not extended. 3. Reader preferences (font, theme, speed) are not persisted — they never were, and they reset per user via the remount. §11 shows how to persist them per user if wanted. 4. A future ApiIdentityProvider (backend JWT as the identity source) is a one-class addition in composition.ts; no repository changes."},{"slug":"production_checklist","title":"Production checklist","folder":"","heading":"Production checklist","id":"","text":""},{"slug":"production_checklist","title":"Production checklist","folder":"","heading":"Production checklist","id":"","text":"Behaviour is unchanged by everything below; these are safety, quality and operability measures."},{"slug":"production_checklist","title":"Production checklist","folder":"","heading":"In the repo","id":"in-the-repo","text":"Security headers (next.config.js): nosniff, frame-options, referrer policy, permissions policy, HSTS, COOP; X-Powered-By removed. Error handling: app/error.tsx (route errors), app/global-error.tsx (layout errors), app/not-found.tsx. Metadata: title template, Open Graph, viewport/theme colour, metadataBase from NEXTPUBLICSITEURL; app/robots.ts keeps account pages out of search. Accessibility: skip-to-content link and a <main> landmark; icon buttons carry aria-labels. Dead code removed: unused ThumbnailPicker and ReadingModeToggle. CI (.github/workflows/ci.yml): typecheck → lint → tests → build on every PR. Locally: npm run check. Editor settings: .editorconfig."},{"slug":"production_checklist","title":"Production checklist","folder":"","heading":"Before go-live (needs your infrastructure)","id":"before-go-live-needs-your-infrastructure","text":"1. Set NEXTPUBLICSITEURL and the API base URL (.env.production.example). 2. Serve over HTTPS (HSTS is on); put a CDN in front of /next/static and /videos. 3. Replace the dev login/dev store with the real backend auth (see docs/DEPLOYMENT.md). 4. Add a Content-Security-Policy once tested against your hosts (Google Fonts are the only third-party origin). 5. Add error monitoring (e.g. Sentry) in app/error.tsx / app/global-error.tsx. 6. Run npm install to create a lockfile and commit it; use npm ci in CI afterwards."},{"slug":"quiz_and_profile","title":"Quiz tracker, quiz-only mode, and profile tabs","folder":"","heading":"Quiz tracker, quiz-only mode, and profile tabs","id":"","text":""},{"slug":"quiz_and_profile","title":"Quiz tracker, quiz-only mode, and profile tabs","folder":"","heading":"Quiz tracker, quiz-only mode, and profile tabs","id":"","text":""},{"slug":"quiz_and_profile","title":"Quiz tracker, quiz-only mode, and profile tabs","folder":"","heading":"Quiz page (app/questions/page.tsx)","id":"quiz-page-appquestionspagetsx","text":"Two columns: the question on the left, components/Quiz/QuestionTracker.tsx on the right (stacks on small screens). Tracker components/ui/AnimatedList.tsx (React Bits, themed with the app tokens through its style prop, so it follows dark/light/sepia). Each question shows: Completed, Marked for review, Skipped or Not answered; header shows \"X of N completed\". Rows show the question text. Three round green buttons under the list filter it: Completed / Marked for review / Not completed (click again to clear; each shows a count). Clicking a row jumps to that question. The quiz is finished with Finish on the last question. The panel is borderless, translucent and blurred, and the page uses the same inertial scrolling as the home page. \"Begin quiz\" now dispatches the chosen question count (GOTOQUESTIONS), preserving quizOnly."},{"slug":"quiz_and_profile","title":"Quiz tracker, quiz-only mode, and profile tabs","folder":"","heading":"Quiz only (no reading)","id":"quiz-only-no-reading","text":"\"Quiz only\" button in the story hero → GOTOQUESTIONS { quizOnly: true }. Results are saved as a history entry with wpm: 0 (excluded from the speed chart); no reading session is created; ResultCard hides the reading/speed rows."},{"slug":"quiz_and_profile","title":"Quiz tracker, quiz-only mode, and profile tabs","folder":"","heading":"Profile tabs (own profile only)","id":"profile-tabs-own-profile-only","text":"Dashboard / Reading history / Analytics / Past test attempts / Settings now swap the content area in place of \"Content posted by you\"; click the active pill again to return. Content lives in components/Account/Panel.tsx; the old routes (/history, /reading-history, /analytics, /settings) reuse the same panels and look unchanged. Other users' profiles still show posts only. Note: AnimatedList's demo icon imports (hugeicons) were removed; not verified in a browser (no build available in the sandbox)."},{"slug":"quiz_and_profile","title":"Quiz tracker, quiz-only mode, and profile tabs","folder":"","heading":"Analytics layout (apple.com-inspired)","id":"analytics-layout-applecom-inspired","text":"Reading speed / Accuracy: two large rounded cards side by side (stacked on mobile) with a centred title, a trend line, an average in brand blue, and the graph below. Consistency (streaks / active days / reading time) and Daily pace: a left-aligned display heading with a blue note on the right, one large card with a two-line caption, then a pill of dots round play button (components/Analytics/PagerPill.tsx). Dots step through the stats (or the latest days for pace); play auto-advances, and starts paused for reduced-motion users. Data, calculations and tooltips are unchanged. Efficiency, Dashboard, Reading history and Past test attempts use the same rounded-[32px] card language (blue notes, display headings, pager on Efficiency)."},{"slug":"quiz_and_profile","title":"Quiz tracker, quiz-only mode, and profile tabs","folder":"","heading":"Notes, QR code and public link","id":"notes-qr-code-and-public-link","text":"New Notes tab (between Dashboard and Reading history): how CN, OS, OOP and DBMS are used in this project, each with a \"Used here\" and a \"Tradeoff\" line. Content lives in lib/notesContent.ts; one view (components/Notes/NotesView.tsx) serves the tab and the public page. On your own profile a QR code (components/Profile/ProfileQr.tsx) replaced the Change photo button; click your avatar to change the photo. The QR is built from the signed-in user's id (lib/qr.ts, no dependency, tested by decoding), so each user gets a different one. Under it, \"Copy notes link\". The QR opens /notes/<userId>, which needs no login (lib/publicRoutes.ts, bypassed in DevLoginGate, navbar hidden). The link always points at the deployed app; set NEXTPUBLICSITEURL to override; the default is the deployed Vercel address in lib/publicRoutes.ts (SITEORIGIN), so the QR works from a phone even when running locally."},{"slug":"quiz_and_profile","title":"Quiz tracker, quiz-only mode, and profile tabs","folder":"","heading":"Uploaded-PDF owner fix","id":"uploaded-pdf-owner-fix","text":"A PDF's pages are images, so a big one can exceed the 5 MB browser storage quota; the save failed silently and the story then looked like it belonged to someone else. CustomStoryRepository now also records the uploader's id in a tiny separate list (customStoryClaims), and SessionManager.findCustomStoryOwner checks it. Test: scripts/session-isolation.test.ts. A PDF too big to store still opens for the session but is not kept in the library."},{"slug":"quiz_and_profile","title":"Quiz tracker, quiz-only mode, and profile tabs","folder":"","heading":"Test timing (start to finish)","id":"test-timing-start-to-finish","text":"ReadingContext stores quizStartedAt (set when \"Begin quiz\" is pressed, via GOTOQUESTIONS) and quizFinishedAt (set by GOTORESULTS). Total test time finish - start, shown on the results page, the quiz panel (live), and in history. Per-question time is the sum of every visit to that question (flushDwell in app/questions/page.tsx), so revisits and unanswered questions are counted. History entries have quizStartedAt; \"Past test attempts\" shows \"Started 10:42 AM · took 12:03\". Each finished test adds its duration to that day's testMs (DailyActivityRepository.recordTestTime); the consistency tracker's hover card shows total reading time and total test time, and a test-only day counts as active. Leaving mid-quiz without finishing records nothing (there is no result to attach it to)."},{"slug":"quiz_and_profile","title":"Quiz tracker, quiz-only mode, and profile tabs","folder":"","heading":"Results page and visual system","id":"results-page-and-visual-system","text":"Results use the site width (max-w-6xl) and the apple.com home-page tile grid: one score tile (rating, copy, two pills, all numbers), then Reading speed and Accuracy tiles side by side (TrendTiles), Time per question (10 rows at a time, \"Show 10 more\" / \"Show less\"), efficiency, and the remaining analytics. The Analytics page uses the same width (PageShell wide). The pager under showcase cards is dots only (no play/pause, no auto-advance). Hover cards share one style (lib/chartStyle.ts). Quiz panel: progress shown like the macOS volume HUD inside a liquid-glass container (components/ui/LiquidGlass.tsx, the navbar's GlassSurface), a separate live \"Total test time\", and white round filter buttons with green strokes. Sign-in / sign-up screens use the same card, display heading, underlined fields and pill tabs as the rest of the app. Behaviour is unchanged."},{"slug":"quiz_and_profile","title":"Quiz tracker, quiz-only mode, and profile tabs","folder":"","heading":"Public notes site (QR code) - documents as web pages","id":"public-notes-site-qr-code---documents-as-web-pages","text":"/notes/<userId> (no login) shows the notes, then every document of this docs/ folder; /notes/<userId>/docs/<slug> shows one document as a web page. Links between documents work, and #section links jump to headings. The page has the landing navbar (glass bar, hamburger and name on the left, theme switch on the right). The hamburger has no personal data (no playlists, search history, uploads or sign-out); it lists the notes and one row per docs folder (Project docs, Interview prep). Opening a folder lists its documents; the one being read is highlighted. How it works: scripts/build-docs.mjs bundles docs//.md into lib/docs/generated.ts (full text, server only) and lib/docs/index.generated.ts (titles only, used by the menu). It runs automatically before dev and build, so new or edited docs appear without extra steps; run npm run docs:build to refresh by hand. lib/docs/markdown.ts turns Markdown into escaped HTML (tests: npm run test:docs). Only .md files are published. docs/DEMOACCOUNTS.csv (demo passwords) is deliberately excluded. Anything you write in a docs/.md file becomes public through the QR link, so keep secrets out of those files."},{"slug":"quiz_and_profile","title":"Quiz tracker, quiz-only mode, and profile tabs","folder":"","heading":"Document pages (public notes)","id":"document-pages-public-notes","text":"Diagrams written as Mermaid blocks are interactive: drag to pan, arrow pad, zoom in/out (Ctrl/⌘ scroll), reset, expand to full screen, copy source. Needs the mermaid package (npm install). Navbar on document pages hides when scrolling down and returns on any scroll up. Research has its own section in the hamburger menu, fed by docs/research/.md. Writing tools for authors: underline, strike, bold italic. (text is accepted but shows as plain text; readers have no select-to-highlight tool on document pages.) Code blocks use a larger font. Search in the centre of the public navbar: a pill that widens on hover/focus; it searches all text on the pages (titles, headings, body, code), shows a snippet with the match highlighted and opens that section; Enter opens the first result. The index is generated into lib/docs/search.generated.ts by scripts/build-docs.mjs and loaded only when the search is used. Diagrams now load Mermaid the ELK layout from a CDN (no npm install needed) and draw like GitHub's viewer (orthogonal arrows). Code blocks are syntax-coloured with indentation kept. Write ts title\"path/to/file.ts\" principle\"What principle it shows\" to show the file path on top and the principle underneath. Any mermaid block becomes an interactive diagram, so new block diagrams can be added the same way. The search bar sits in the centre of the navbar."},{"slug":"quiz_and_profile","title":"Quiz tracker, quiz-only mode, and profile tabs","folder":"","heading":"Question types (quiz JSON)","id":"question-types-quiz-json","text":"Besides single-choice, the quiz JSON can contain: Select all that apply — \"correctAnswer\": [0, 2] (indexes, letters or option texts). Marked right only when exactly that set is chosen. Typed number — \"options\": [] and \"correctAnswer\": 4.25. Whole numbers must match exactly; decimals are accepted within ±0.01 (set \"tolerance\" to change). The quiz shows checkboxes or a number box with a Check answer button (leaving the question submits what was entered), and results, timing and accuracy use the same grading (lib/grading.ts). A sample is in scripts/fixtures/gate-cs1-2026.json; tests are in scripts/quiz.test.ts."},{"slug":"quiz_and_profile","title":"Quiz tracker, quiz-only mode, and profile tabs","folder":"","heading":"Quiz JSON: optional labels and code in questions","id":"quiz-json-optional-labels-and-code-in-questions","text":"Each question may also carry these optional fields (none are required): chapter, topic, year (year the previous-year question appeared, e.g. 2026; also accepted as pyqYear) and note (shown on the results page after the test). Chapter, topic and year appear as small chips above the question while taking the quiz. The one-by-one editor has matching optional boxes. Code in a question is shown as a code block with its indentation and line breaks kept and syntax colours. Write it in the JSON with \\n line breaks (and spaces for indentation), or wrap it in a Markdown fence inside the string ( c … ). Plain-text questions with pasted code lines are detected automatically. Options that span several lines are shown as code too."},{"slug":"reading_presence","title":"Reading status, total reading time, theme & uploads","folder":"","heading":"Reading status, total reading time, theme & uploads","id":"","text":""},{"slug":"reading_presence","title":"Reading status, total reading time, theme & uploads","folder":"","heading":"Reading status, total reading time, theme & uploads","id":"","text":""},{"slug":"reading_presence","title":"Reading status, total reading time, theme & uploads","folder":"","heading":"Reading status (heartbeat)","id":"reading-status-heartbeat","text":"lib/readingPresence.ts works like WhatsApp's \"online\". Every 5 seconds a heartbeat checks: 1. the person is on a reading surface (story article in view, /read, or the playing /reader), 2. the tab is visible, and 3. they did something (scroll, key, pointer, touch) in the last 60 seconds. All true → the navbar shows ● Reading beside the clock and the beat adds its elapsed time to the user's total. Any false → status drops to idle on the next beat and nothing is added. A sleeping laptop adds at most two beats. Totals are stored per user (speed-reader:reading-time:<userId>) and shown next to the profile photo (hover for the full text). components/Session/PresenceTracker.tsx wires the browser in; tests: npm run test:presence."},{"slug":"reading_presence","title":"Reading status, total reading time, theme & uploads","folder":"","heading":"Theme","id":"theme","text":"The default follows the system light/dark setting and updates live. Choosing a theme yourself (switch or Settings) is remembered and wins from then on."},{"slug":"reading_presence","title":"Reading status, total reading time, theme & uploads","folder":"","heading":"Uploading","id":"uploading","text":"PDF/image upload now opens a modal in the same design as \"Add your own story\"; quiz questions can be typed one by one or pasted / loaded as JSON. Dragging a story .json, PDF or image onto the landing page behaves exactly like the upload button (it shows a \"Drop to upload\" overlay)."},{"slug":"reading_presence","title":"Reading status, total reading time, theme & uploads","folder":"","heading":"Story page","id":"story-page","text":"The stats, About, reading-speed card and Start/Bookmark block below the article were removed; the navbar no longer shows WPM readouts."},{"slug":"story_page","title":"Story page","folder":"","heading":"Story page","id":"","text":""},{"slug":"story_page","title":"Story page","folder":"","heading":"Story page","id":"","text":"The page at / once a story is loaded (components/Dashboard/Dashboard.tsx)."},{"slug":"story_page","title":"Story page","folder":"","heading":"Layout (top to bottom)","id":"layout-top-to-bottom","text":"1. Hero (components/Dashboard/StoryHero.tsx) – the story's uploaded video plays muted/looping, with the thumbnail as poster (falls back to the thumbnail, then a gradient). Title, a stats pill, Read below and a blue Start reading (practice mode) button. 2. Author / follow / content actions / Edit. 3. The full story, in reading mode by default (ReadingModePage with embedded) – no toggle needed. 4. Reading stats, About this story, Reading speed, Start reading Bookmark."},{"slug":"story_page","title":"Story page","folder":"","heading":"Reading extras (only while the article is in view)","id":"reading-extras-only-while-the-article-is-in-view","text":"Progress bar fixed at bottom-0, in BRANDBLUE (#306fdb, lib/brand.ts). Section rail on the right (ScrollRail side\"right\"), active mark in the same blue. Text size A−/A pill (80%–180%), remembered in localStorage (speed-reader.story-font-scale); implemented with the --sr-scale CSS variable in readingMode.css (.sr-embedded)."},{"slug":"story_page","title":"Story page","folder":"","heading":"Moved","id":"moved","text":"\"Past test attempts\" now lives in the hamburger menu and opens /history."},{"slug":"story_page","title":"Story page","folder":"","heading":"Unchanged","id":"unchanged","text":"/read (the toggled reading mode) still uses the left rail and the navbar progress bar."},{"slug":"story_page","title":"Story page","folder":"","heading":"Section list & speed wheel","id":"section-list-speed-wheel","text":"The right-hand section list is always open on wide screens; clicking one of the dashes scrolls to that section and hides/shows the list (ScrollRail alwaysOpen). A speed wheel (components/ui/OptionWheel.tsx, from React Bits; wrapped by ReadingMode/SpeedWheel.tsx) sits at the left edge. Turn it to pick any reading speed. The navbar clock counts down from words ÷ wpm in real time. It starts when the controls appear and never depends on scrolling. All controls (section list, speed wheel, text size, bottom progress bar) appear once the hero has scrolled away and hide again as it returns from the top."},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"Story text editor — design, OOP, CN, OS and DBMS","id":"","text":""},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"Story text editor — design, OOP, CN, OS and DBMS","id":"","text":"This document covers the rich text editor that replaced the plain <textarea> in Add your own story and Edit story. Only the text box changed. The guided form fields, the question editor, the JSON tab, the reading engine, the design system and the per-user session layer are untouched. Everything below describes code that exists in this repo. Section 9 lists what is not done, so nothing here should be read as a claim beyond it."},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"1. What the user gets","id":"1-what-the-user-gets","text":"Area Implemented Text bold, italic, underline, strike, sub/superscript, font family (any name, with suggestions), font size (any px value), font colour and highlight (palette, recent colours, HEX / rgb() / hsl() entry, reset), clear formatting Blocks Title, Subtitle, Heading 1–6, Quote, alignment (left/centre/right/justify), bullet, numbered (nesting via Tab/ShiftTab), checklists (clickable), indent/outdent, line spacing, space before/after, paragraph background Insert links (CtrlK, scheme allow-list), images, tables, code blocks, horizontal rule, page break, symbols, equations (LaTeX-lite → Unicode), footnotes Code blocks a real code-editor widget per block (see §4.3): 17 languages incl. JS/TS/Python/Java/C/C/C#/Go/Rust/PHP/HTML/CSS/JSON/SQL/Bash/Markdown, highlighting, auto-indent/dedent, bracket/quote pairing, Tab/ShiftTab, Ctrl/ comment, line numbers, current-line highlight, find/replace, wrap, visible whitespace, indent width 2/4/tab, dark/light code theme, copy, clear, delete, \"convert selection to code block\", js Enter shortcut Images file picker, drag & drop, paste; downscaled to ≤1600 px; corner-handle resize (Shift free aspect); left/centre/right; S/M/L; alt text; caption; border; spacing; replace; crop 1:1 / 4:3 / 16:9; delete Tables insert R×C; add/delete rows and columns; merge right/down; split; cell colour; borders toggle; Tab moves between cells (adds a row at the end) Review / View find & replace (match case, highlight), word / character / paragraph / code-block counts, reading time, document properties; continuous or page view, zoom 50–200 %, outline navigation, paper size, orientation, margins, header/footer text, page background, three paper themes Fullscreen Expand button, F11, Esc to exit; caret, selection, scroll and unsaved edits survive (§5.2) Documents title rename inline, autosave status, Save (CtrlS) / Save as copy / New / Open / Delete, crash recovery, import .txt .md .html .json, export .docx .md .html .txt, PDF through the browser print dialog Keyboard: CtrlZ / CtrlY (own history), CtrlB/I/U, CtrlK, CtrlF, CtrlS, F11, Tab / ShiftTab."},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"2. How it plugs into the existing app","id":"2-how-it-plugs-into-the-existing-app","text":"AddStoryModal / EditStoryModal │ <StoryTextEditor draftSlot onChange initial> components/Editor/StoryTextEditor.tsx │ builds DocumentStore from sessionManager.active().namespace ▼ EditorView (React shell: ribbon, status bar, menus) components/Editor/EditorView.tsx │ EditorSurface (contenteditable history paste/drop) components/Editor/engine/ │ getHtml() → RichDocument.withHtml() → sanitize ▼ RichDocument (immutable) ──► Blocks (typed model) ──► exporters / stats / reading text │ DocumentStore ──► KeyValueStore UserNamespace (existing session layer, not modified) storyBridge.ts is the only adapter between a story and the editor. On save the story keeps its normal story: [{ paragraph }] (the reading engine is unchanged) and gains an optional richDocument snapshot. If the plain paragraphs are edited elsewhere (for example in the JSON tab) the snapshot no longer matches and is ignored, so what the reader shows is always the source of truth. The JSON tab is unchanged. Pasting JSON still goes through addCustomStory, and richDocument in JSON is treated as untrusted input like everything else. Sessions: nothing in lib/session was edited. DocumentStore borrows the active user's UserNamespace, so another user's documents are unreachable by key construction. SessionBoundary remounts the tree on user switch, so the store is rebuilt for the new user."},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"3. File map","id":"3-file-map","text":"lib/editor/ html/ entities, HtmlNode, HtmlParser, HtmlSerializer, SanitizePolicy, HtmlSanitizer model/ Blocks (Block hierarchy BlockVisitor), BlockExtractor, RichDocument export/ Exporter (interface), TextExporters (txt/md/html), DocxExporter, ZipWriter, ExporterRegistry import/ Importers (txt, md, html) ImporterRegistry code/ Tokenizer, languages, CodeEditingEngine persistence/ DocumentStore, ImageStore logic (inside DocumentStore), AutosaveScheduler, EditLock, EditorPrefs format/ TexLite util/ LruCache, crc32, hash storyBridge.ts components/Editor/ StoryTextEditor.tsx (composition root) EditorView.tsx (React shell) editor.css engine/ EditorSurface, CodeBlockWidget, ImageResizer, TableOps, commands, HistoryStack, SelectionMemento, FullscreenController ui/ Ribbon, ColorPopover, icons scripts/editor.test.ts (40 tests, npm run test:editor) lib/editor has no React and no DOM dependency (it runs under Node in the tests); components/Editor is the only layer that touches the browser."},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"4. OOP — where and why","id":"4-oop-where-and-why","text":""},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"4.1 Document model (lib/editor/model)","id":"41-document-model-libeditormodel","text":"Concept Where Why Abstraction inheritance abstract class Block with ParagraphBlock, HeadingBlock, ListBlock, CodeBlock, ImageBlock, TableBlock, RuleBlock, PageBreakBlock, FootnotesBlock one contract (kind, accept, isEmpty) for every kind of content Immutability / value objects every block field is readonly; InlineRun is a value; RichDocument.withHtml/withMeta/withPage return new instances undo history, autosave diffing and React state can never see a half-mutated object Visitor (double dispatch) BlockVisitor<R> implemented by PlainTextVisitor, MarkdownVisitor, DocxVisitor, StatsVisitor, PlainParagraphVisitor format-specific behaviour lives outside the blocks. A new export format is a new visitor and no block class changes (Open/Closed) Encapsulation RichDocument has a private constructor and static factories (fromHtml, fromSnapshot, empty). fromHtml always sanitizes it is impossible to build a document holding unsanitized HTML Single responsibility BlockExtractor is the only code that understands HTML structure; the sanitizer only filters; the serializer only prints a fix to \"how nested lists are read\" is made once Lazy cached derivation RichDocument.blocks and .stats computed once per immutable instance"},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"4.2 Pipeline objects","id":"42-pipeline-objects","text":"HtmlSanitizer(parser, serializer, stylePolicy) takes its collaborators through the constructor (Dependency Inversion), so a stricter policy can be injected. StylePolicy and SanitizePolicy.ts express the allow-list as data plus a small object. DocumentExporter / DocumentImporter are Strategy interfaces; ExporterRegistry / ImporterRegistry hold them (Open/Closed, Liskov: every exporter is substitutable). ListNumbering owns the numbering rule once and is shared by the text and Markdown visitors."},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"4.3 Editing layer (components/Editor/engine)","id":"43-editing-layer-componentseditorengine","text":"Concept Where Command EditorCommand, ExecCommand, FnCommand, CommandRegistry. Ribbon buttons, shortcuts and tests all call registry.run(id) Memento HistoryStack (bounded snapshot history) and SelectionMemento (caret survives focus loss and fullscreen) Facade EditorSurface hides contenteditable quirks behind setHtml / getHtml / exec / insertImageFile / find…; React only talks to it Adapter CodeBlockWidget adapts a <textarea> highlight overlay to the editor. The editing rules are in the DOM-free CodeEditingEngine, so a CodeMirror adapter could replace the widget only Data-driven polymorphism one Tokenizer class driven by a LanguageSpec object per language instead of 17 lexers Pure functions as strategy CodeEditingEngine.tab/enter/type/backspace/toggleComment take state and return new state, so they are tested with no DOM State machine encapsulation FullscreenController (idle → native-fullscreen or fallback → exit) and ImageResizer (pointer drag) own their lifecycles and dispose() their listeners Static utility class TableOps builds a grid (a spanning cell occupies several slots) before every operation"},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"4.4 Persistence","id":"44-persistence","text":"DocumentStore, EditorPrefsRepository, EditLock, AutosaveScheduler<T> (generic), LruCache<K,V> (generic) are small single-purpose classes composed in StoryTextEditor.tsx, the composition root of this feature, in the same style as lib/session/composition.ts."},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"5. OS concepts (as implemented)","id":"5-os-concepts-as-implemented","text":""},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"5.1 Scheduling, buffering, write coalescing","id":"51-scheduling-buffering-write-coalescing","text":"AutosaveScheduler is a debounced write-back buffer: a burst of keystrokes becomes one write 800 ms after the last, like OS page-cache write-back. flush() runs on pagehide and visibilitychange → hidden and on unmount, so the last keystrokes are not lost. Heavy work is deferred with timers: document sync is trailing-throttled to 180 ms, history records after 450 ms of quiet, resize handles use pointer events and ResizeObserver."},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"5.2 Resources, limits, memory","id":"52-resources-limits-memory","text":"History is bounded (150 snapshots); LruCache (8 entries) keeps recently opened bodies; images are downscaled to ≤ 1600 px before storing; images > 12 MB are refused; storage quota failures raise StorageFullError instead of crashing. The fullscreen controller first uses the Fullscreen API without moving DOM. If it is denied, the root node is re-parented to <body> (a position: fixed element inside a transformed modal would not cover the viewport) and the selection is restored from the memento."},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"5.3 Synchronisation and mutual exclusion","id":"53-synchronisation-and-mutual-exclusion","text":"EditLock is a lease lock: the holder renews a timestamp every lease/3; a crashed tab's lease expires, so the lock cannot deadlock. The second tab opens the document read-only. After the write it re-reads to detect a racing writer. (This is cooperative locking over localStorage, not a kernel mutex.) DocumentStore.save also uses optimistic versions (see §7) so even without the lock a stale tab gets VersionConflictError."},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"5.4 Process/lifecycle","id":"54-processlifecycle","text":"Page lifecycle hooks (pagehide, visibilitychange) are used the way an OS uses shutdown hooks. Every long-lived object has dispose() (listeners, observers, locks)."},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"6. CN (computer networks) concepts (as implemented)","id":"6-cn-computer-networks-concepts-as-implemented","text":"The editor is offline by design; it makes no network requests. The networking ideas that are in the code: Concept Where Untrusted input at a trust boundary pasted HTML, JSON-supplied HTML, imported files and even localStorage are parsed and sanitized (§8). Same stance as validating an HTTP request body URL / scheme handling isSafeUrl strips control characters inside the scheme (blocks java\\tscript:), then allows http/https/mailto/tel for links and http/https/data(image only)/sr-img for images. Links opened in a new tab get rel\"noopener noreferrer\" Media types (MIME) image type allow-list (png jpeg gif webp avif), data: URL parsing (RFC 2397 base64), correct export MIME types (application/vnd.openxmlformats-officedocument.wordprocessingml.document, text/markdown;charsetutf-8…) Content negotiation analogue paste prefers text/html, falls back to text/plain, handles Files — like choosing a representation from an Accept list Error detection crc32.ts is the IEEE CRC-32 used in each ZIP entry (same polynomial as Ethernet's FCS), checked against the standard test vector 123456789 → 0xCBF43926 Framing / binary container ZipWriter writes local headers, central directory and end-of-central-directory records byte by byte (little-endian) Character encoding UTF-8 via TextEncoder for ZIP names and parts; names flagged UTF-8 Content addressing / idempotency an image's id is a SHA-256 prefix of its bytes (sr-img:<hash>), so storing it twice is a no-op, like a content-addressed cache Download semantics Blob object URL download attribute, the client-side analogue of Content-Disposition: attachment Not implemented: no sockets, no server sync for documents, no retry/backoff (there is nothing remote to retry). The backend still accepts only paragraphs: string[]."},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"7. DBMS concepts (as implemented)","id":"7-dbms-concepts-as-implemented","text":"DocumentStore is a tiny per-user database over the app's KeyValueStore (localStorage). It is not SQL and not crash-proof ACID; it applies the ideas that fit a key-value medium. Logical schema (per user namespace srt:v2:u:<user>:docs:…) Table (key) Row Notes index {id PK, title, words, updatedAt, version, bytes}[] small, read often (a covering index for the Documents menu) body:<id> RichDocumentSnapshot large, read on open. Split from index on purpose (normalisation / vertical partitioning), so listing never parses document bodies img:<hash> data URL content-addressed: natural de-duplication; n:m with bodies draft:<slot> snapshot write-ahead style recovery copy lock:<id> {owner, until} lease row (§5.3) prefs editor UI preferences Mechanisms Primary key / uniqueness: newId(); save replaces by id. Transaction with rollback: save writes body then index; if the index write fails (quota) the body is restored to its previous value. Tested. Optimistic concurrency: each row has version; save(id, doc, expected) throws VersionConflictError if it changed. Tested. Referential integrity / GC: collectGarbage() scans bodies and drafts for sr-img: references and deletes unreferenced images (reference counting by scan); remove() calls it. Tested. Consistency check (fsck): repair() drops index rows without a body. Tested. Caching: LruCache in front of body reads. Tenant isolation: the namespace prefix; the test proves a second user sees nothing (documents are isolated per user). Integrity constraints on read: stored snapshots are re-validated (fromSnapshot clamps margins, whitelists enums) and re-sanitized; a tampered localStorage value cannot inject script (tested). Normal form of content: documents are stored as sanitized HTML plus metadata; the typed Block model is derived (not stored twice), avoiding update anomalies. Limits: localStorage is ≈ 5 MB per origin and synchronous; there is no multi-statement durability guarantee if the browser dies mid-write."},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"8. Security: the sanitizer is the trust boundary","id":"8-security-the-sanitizer-is-the-trust-boundary","text":"HTML can reach the editor from the JSON tab, paste, imports, shared stories and storage. It is later assigned to innerHTML, so HtmlSanitizer is a white-list: unknown tags are unwrapped; script style iframe object embed svg math form input … are removed with their content; attributes: only per-tag allow-list plus style/class/title/lang/dir and a fixed set of data- (no on ever survives); classes must match sr-; CSS: per-property validators; any value with url(, expression(, javascript:, @import, backslashes or <> is dropped; URLs: see §6; SVG data URLs are rejected; nesting deeper than 64 is flattened to text (stack-exhaustion guard); the result is idempotent (sanitize(sanitize(x)) sanitize(x), tested). Code blocks are stored as <pre data-lang><code>text</code></pre> with the text escaped, and are rebuilt from the textarea value on save, so code survives save / reopen / export (tested, including in a real browser)."},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"9. Honest gaps and trade-offs","id":"9-honest-gaps-and-trade-offs","text":"1. No Monaco / CodeMirror. The package registry was unreachable in the build environment, so the code widget is hand-written (textarea over a highlighted <pre>). It is structured so CodeMirror 6 can replace CodeBlockWidget alone. 2. Code folding has no UI. CodeEditingEngine.foldRanges() computes brace/indent ranges (tested) but the widget does not render fold markers. Autocomplete is not implemented. 3. Page view is visual, not true pagination. It shows paper width, margins, page guide lines, header and footer once. Real per-page numbering and automatic page breaking happen only in the exported .docx / print output. 4. document.execCommand (deprecated but universal) does the inline formatting. Undo/redo is the editor's own snapshot history so widget and table changes undo correctly; caret restoration after undo is by text offset. 5. Find matches within a single text node, so a hit spanning bold/plain boundaries is missed. Find inside code blocks uses the widget's own bar (CtrlF in the block). 6. Tables: table-level border toggle and per-cell colour, but no column-width dragging or per-cell border styles. 7. Multilevel lists: nesting works; the editor shows the browser default markers, the .docx uses decimal / letter / roman by depth. 8. Equations are a LaTeX-lite → Unicode renderer, not a TeX engine. 9. Footnotes are numbered on insertion and not renumbered after deletion. 10. Images are stored in localStorage (downscaled); many large images will hit the quota (a clear error is shown). No cropping beyond centre aspect presets. 11. DOCX/PDF import is not supported. Import: .txt .md .html .json. PDF export uses the browser's print dialog. 12. Backend: the standalone API accepts only paragraphs: string[], so the rich snapshot stays on the device; the plain text is what a backend would receive. 13. Verification: logic is covered by npm run test:editor (40 tests, Node) and the DOCX was opened with LibreOffice and python-docx. The UI was exercised in headless Chromium (typing, undo, headings, code-block editing, table merge/split, image resize, fullscreen, find/replace, XSS paste, save/export). It was not tested in Firefox/Safari, and a full next build could not be run here (no dependency install possible), so run npm install && npm run build once."},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"10. Running the tests","id":"10-running-the-tests","text":"npm run test:editor # model, sanitizer, exporters, code engine, store, lock, autosave npm run test:session # existing per-user session isolation (unchanged)"},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"11. Reader support (images, tables, code) and quiz-question input","id":"11-reader-support-images-tables-code-and-quiz-question-input","text":""},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"11.1 The reader now shows what you wrote","id":"111-the-reader-now-shows-what-you-wrote","text":"components/Reader/Reader.tsx renders a story written in the editor from its rich snapshot instead of flat paragraphs, so images, captions, tables, headings, lists, links and highlighted code blocks appear in the reading view. Stories without a snapshot (JSON stories, built-in stories) render exactly as before. StoryContentRenderer (lib/editor/reader/) is a pure class: sanitized HTML tree → resolve sr-img: references → syntax-highlight <pre> with the same Tokenizer the editor uses → drop neutral text/background colours → sanitize again → string. Nothing it produces can contain a tag, attribute, class, style or URL the allow-list forbids (tested with a hostile snapshot). createStoreImageResolver looks an image up in the active user's namespace first, then in any other user's row with the same content hash (so an adopted story keeps its pictures). Whatever it finds is re-validated as a base64 raster data URL; a tampered value becomes an \"Image unavailable\" note, never a javascript:/SVG source. Black/white/grey text colours are removed in the reader so author-chosen black text cannot disappear on the dark theme; chromatic colours (red, blue …) are kept. The reading engine is untouched: progress is time-based and the scroll position is derived from the live track height (ResizeObserver), so taller content such as images needs no engine change. The \"paragraph x of N\" label counts the plain paragraphs (code text and captions included). The snapshot is used only while it still matches story.story (richDocFor), so text edited elsewhere (for example the JSON tab) is always what the reader shows. GC fix: DocumentStore.collectGarbage() now scans the user's whole namespace, including saved stories, so an image used by a story is never deleted when its editor draft or document is removed (tested). Images live in browser storage per user; a story JSON copied to another browser does not carry its images (they show as \"Image unavailable\")."},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"11.2 Adding quiz questions: one by one or JSON / file","id":"112-adding-quiz-questions-one-by-one-or-json-file","text":"components/Search/QuestionsInput.tsx is used by both Add story and Edit story (media stories keep their existing flow). A toggle switches between: One by one — question, options (add/remove), correct-answer radio, explanation, delete question. JSON / file — type or paste JSON, drop a .json/.txt file onto the box, or use Load file; Insert example gives a template. Both views edit the same list, so you can paste 30 questions, switch to \"One by one\" and fix one, and switch back; edits show up in the JSON. The JSON pane is live: valid JSON replaces the list immediately; invalid JSON keeps the last good list, shows what is wrong by question number, and disables Add story / blocks Save until fixed. Accepted JSON (lib/questionImport.ts, tested): an array, { \"questions\": [...] } (so a whole story JSON works), or a single question; optionally inside a json fence. Per question: question (q, text), options (choices, answers; 2–12, no blanks or duplicates), correctAnswer (answer, correct, correctIndex, correctOption) and explanation (explain, rationale). The answer may be a 0-based number, a letter (\"B\") or the exact option text; anything else is reported, never guessed. Limits: 200 questions, 1 MB file. The existing story validation still requires at least one question for a text story."},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"12. Code in the reader: IDE-style formatting","id":"12-code-in-the-reader-ide-style-formatting","text":"Every code snippet is shown on its own lines with indentation kept, highlighted, in a scrollable block (white-space: pre, 4-wide tabs, no ligatures, no inherited letter-spacing). Editor code blocks: dedented, language guessed if \"plaintext\", and code whose line breaks were lost (one long line) is re-flowed by beautifyIfCollapsed (brace languages and JSON; strings and comments are never touched; code that already has several lines is never rewritten). Stories without a rich snapshot (JSON, PDF, old saves): plainStoryToHtml finds fences and multi-line paragraphs that look like code (looksLikeCode, a conservative line-scoring heuristic) and renders them the same way. Other multi-line prose keeps its line breaks. Stories with no code keep the original plain layout. Code lives in lib/editor/code/CodeHeuristics.ts, lib/editor/reader/CodeFormatter.ts, lib/editor/reader/plainStoryHtml.ts; 6 tests cover it."},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"13. One-click \"Format code\"","id":"13-one-click-format-code","text":"Each code block has a { } button (and ShiftAltF inside the block) that formats the whole block in its language. If the block is plain text, the language is guessed first and the block switches to it. CtrlZ undoes a format. lib/editor/code/formatCode.ts (Strategy pattern, one strategy per language family): JSON: parse and pretty-print (invalid JSON falls back to bracket indentation). HTML: tag-depth layout; <script> / <style> bodies are formatted as JS / CSS; <pre> / <textarea> stay untouched. Python: indentation levels are re-derived and re-emitted with the chosen indent (tabs and mixed widths fixed). Lines are never joined or split, because indentation is Python's meaning. SQL: keywords upper-cased, one clause per line, one column per line, AND/OR indented. Bash: if/fi, do/done, case/esac, { } blocks. JS, TS, Java, C, C, C#, Go, Rust, PHP, CSS and anything else: re-indent by bracket depth; a single collapsed line is split into statements first. Strings and comments are never changed (decided by the language Tokenizer). Formatting is idempotent, and on any internal error the original code is kept. Uses the block's indent setting (2 / 4 / tab). Also fixed: unterminated-string/comment matching in the Tokenizer used $ with the multiline flag, which ended triple-quoted strings at the first line; Python ''' strings are now recognised."},{"slug":"text_editor","title":"Story text editor — design, OOP, CN, OS and DBMS","folder":"","heading":"13.1 Code whose line breaks were lost","id":"131-code-whose-line-breaks-were-lost","text":"The ✦ Format button sits right next to the language selector. Code pasted or saved as a single line usually keeps the old indentation as a run of 2 spaces where each newline was. splitOnWideGaps turns those gaps back into line breaks (after ;, {, } and after a // comment; also ;}), never inside strings, and the result is then re-indented. If the block is \"Plain text\" and looks like C-family code (typed declarations, generics, braces), it is detected as Java. The reader uses the same logic for one-line code."},{"slug":"interview--01-javascript-typescript","title":"01 · JavaScript & TypeScript","folder":"interview","heading":"01 · JavaScript & TypeScript","id":"","text":""},{"slug":"interview--01-javascript-typescript","title":"01 · JavaScript & TypeScript","folder":"interview","heading":"01 · JavaScript & TypeScript","id":"","text":""},{"slug":"interview--01-javascript-typescript","title":"01 · JavaScript & TypeScript","folder":"interview","heading":"Easy","id":"easy","text":"1. var vs let vs const? var is function-scoped and hoisted (initialised undefined); let/const are block-scoped with a temporal dead zone. const forbids rebinding, not mutation. 2. vs ? coerces types; doesn't. Use ; the one idiom for is x null. 3. What is a closure? A function plus the variables of the scope it was created in. Used for private state, memoisation, debouncing. Here: useInertiaScroll keeps target in a closure shared by the wheel/key handlers. 4. map / filter / reduce? Pure array transforms returning new values; forEach returns nothing. 5. null vs undefined? undefined never assigned; null intentionally empty. 6. TS: interface vs type? Both describe shapes; interfaces merge and extend, types do unions/intersections/mapped types."},{"slug":"interview--01-javascript-typescript","title":"01 · JavaScript & TypeScript","folder":"interview","heading":"Medium","id":"medium","text":"1. Explain the event loop. Call stack → microtask queue (promises, queueMicrotask) drained fully → one macrotask (timers, I/O, events) → render → repeat. await continues as a microtask. Consequence: a never-ending microtask chain starves rendering. 2. How does this work? Determined by call-site: method call, call/apply/bind, new, default (undefined in strict mode). Arrow functions capture lexical this. 3. Debounce vs throttle — implement debounce. const debounce <A extends unknown[]>(fn: (...a: A) > void, ms: number) > { let t: ReturnType<typeof setTimeout>; return (...a: A) > { clearTimeout(t); t setTimeout(() > fn(...a), ms); }; }; 4. Promise combinators. all (fails fast), allSettled (never rejects), race (first to settle), any (first to fulfil). Know which to use for \"load all or fail\" vs \"best effort\". 5. Prototype chain & class. Classes are syntax over prototypes; method lookup walks proto. Here: the editor engine and backend classes use ES classes — see docs/OOPARCHITECTURE.md. 6. TS generics & narrowing. Discriminated unions exhaustive switch with a never check. Here: ReadingContext actions are a discriminated union on type. 7. Why does TS narrow let x: T null null to null? Control-flow analysis sees only the assignment, not closure writes — cast null as T null (fixed in formatCode.ts)."},{"slug":"interview--01-javascript-typescript","title":"01 · JavaScript & TypeScript","folder":"interview","heading":"Hard","id":"hard","text":"1. Implement Promise.all / a promise pool with concurrency N. Maintain an index and N workers each pulling the next task; resolve when all settle; keep result order by index. 2. Memory leaks in SPAs. Detached DOM nodes, un-removed listeners/intervals, closures holding big objects, unbounded caches. Detect: heap snapshots, \"detached\" filter. Here: every useEffect that adds a listener/requestAnimationFrame returns a cleanup. 3. Deep clone / deep equal edge cases. Cycles (WeakMap), Dates, Maps/Sets, property descriptors, structuredClone limits (no functions). 4. TS advanced types. Build DeepReadonly<T>, Pick-by-value-type, a typed EventEmitter<Events>; explain variance, infer, template-literal types. 5. Module systems. ESM (static, live bindings, tree-shakable) vs CJS (dynamic, copies); dual-package hazards; why Next needs \"use client\" boundaries. 6. Design an undo/redo stack for a rich-text editor. Command pattern coalescing of typing bursts selection snapshots. Here: the dependency-free editor in lib/editor/."},{"slug":"interview--02-react","title":"02 · React","folder":"interview","heading":"02 · React","id":"","text":""},{"slug":"interview--02-react","title":"02 · React","folder":"interview","heading":"02 · React","id":"","text":""},{"slug":"interview--02-react","title":"02 · React","folder":"interview","heading":"Easy","id":"easy","text":"1. Props vs state? Props flow down and are read-only; state is owned by a component and triggers re-render when changed. 2. Why key in lists? Stable identity so reconciliation reuses/moves the right DOM state. Never use array index for reorderable lists. 3. Controlled vs uncontrolled inputs? Controlled: value in state. Uncontrolled: DOM owns it, read via ref. 4. useEffect dependency array? Re-run when deps change; [] mount/unmount only. Return a cleanup. 5. What is lifting state up? Move shared state to the nearest common parent."},{"slug":"interview--02-react","title":"02 · React","folder":"interview","heading":"Medium","id":"medium","text":"1. useMemo / useCallback — when? Only for referential stability to memoised children/effects or expensive computation. Measure first; they cost memory and complexity. 2. useReducer vs useState? Reducer for related transitions and testable logic. Here: ReadingContext is a reducer (SETREADINGMODE is ignored during reading/completed — a business rule living in one place). 3. Context pitfalls? Every consumer re-renders when the value changes. Split state/dispatch contexts (done here: useReadingState / useReadingDispatch), memoise values, or use selector libraries. 4. Why do effects run twice in dev? StrictMode double-invokes mount/unmount to expose missing cleanups. Fix the effect, don't remove StrictMode. 5. Stale closure bug? Handler captured an old state value. Fix with functional updates (setN(n > n1)), refs, or correct deps. 6. Hydration mismatch causes? Different server/client output (Date.now, window, localStorage). Read browser-only data in useEffect. Here: PlatformShowcase loads history in an effect, not during render. 7. Error boundaries? Class/error.tsx catch render errors in the subtree (not event handlers or async). See app/error.tsx."},{"slug":"interview--02-react","title":"02 · React","folder":"interview","heading":"Hard","id":"hard","text":"1. Explain reconciliation, Fiber and concurrent rendering. Fiber makes work interruptible; transitions mark updates low-priority; useDeferredValue/startTransition keep input responsive; renders must be pure because they can be repeated/abandoned. 2. Optimise a 10k-row list. Virtualise (windowing), memoise rows, stable keys, avoid inline object props, move state down, batch updates, use content-visibility. 3. Design a custom hook that drives a rAF loop safely. Keep mutable state in refs, one requestAnimationFrame chain, cancel on unmount, respect prefers-reduced-motion, pause when hidden. Here: useInertiaScroll, useReadingEngine. 4. Server Components vs Client Components. RSC render on server, ship no JS, can't use state/effects; client components hydrate. Push \"use client\" to the leaves; pass server data down as props. 5. State management at scale. Server cache (React Query/SWR) vs UI state vs URL state vs form state; avoid one global store for everything. 6. Accessible custom widget. Roles, keyboard map, focus management/trapping, aria-live; Here: the scroll rail uses buttons with labels; the carousel buttons have aria-labels and disabled states."},{"slug":"interview--03-nextjs-web-platform","title":"03 · Next.js & Web Platform","folder":"interview","heading":"03 · Next.js & Web Platform","id":"","text":""},{"slug":"interview--03-nextjs-web-platform","title":"03 · Next.js & Web Platform","folder":"interview","heading":"03 · Next.js & Web Platform","id":"","text":""},{"slug":"interview--03-nextjs-web-platform","title":"03 · Next.js & Web Platform","folder":"interview","heading":"Easy","id":"easy","text":"1. App Router vs Pages Router? app/ uses nested layouts, Server Components by default, loading/error/not-found conventions; pages/ uses getServerSideProps etc. 2. What is \"use client\"? Marks a module (and its imports) as part of the client bundle; needed for hooks, browser APIs, event handlers. 3. CSS box model; position values? content/padding/border/margin; static, relative, absolute, fixed, sticky. 4. Flexbox vs Grid? Flex one dimension; Grid two. 5. What does next build do? Compiles, type-checks, statically renders what it can, emits .next."},{"slug":"interview--03-nextjs-web-platform","title":"03 · Next.js & Web Platform","folder":"interview","heading":"Medium","id":"medium","text":"1. Why does importing plain .css in a component error? Next.js only allows global (non-module) CSS to be imported from the root layout (and app in Pages). Anywhere else the build rejects it to keep global CSS order predictable. Fixes: (a) import in app/layout.tsx (what this project does, in a fixed order after globals.css), (b) use .module.css, (c) Tailwind utilities. Rule here: components never import .css. 2. Rendering modes. SSG, SSR, ISR, CSR, streaming; when to pick each (SEO freshness cost). 3. Data fetching & caching in App Router. fetch caching, revalidate, cache: \"no-store\", route segment config, revalidatePath/Tag. 4. Core Web Vitals. LCP (largest image/text — preload hero, optimise fonts), INP (long tasks — split work, startTransition), CLS (reserve space for images/fonts). 5. Specificity & stacking contexts. Here: a positioned footer painted over a fixed page with no in-flow content, hiding /reader; fix was to not render the footer on that route. 6. Tailwind pros/cons. Design tokens via CSS variables (rgb(var(--ink))) enable three themes without duplicating classes; purge keeps CSS small; drawback: long class strings → extract components. 7. env handling. Only NEXTPUBLIC reaches the browser and is inlined at build time; server secrets never get that prefix."},{"slug":"interview--03-nextjs-web-platform","title":"03 · Next.js & Web Platform","folder":"interview","heading":"Hard","id":"hard","text":"1. Walk through what happens from typing a URL to pixels. DNS, TCP/TLS, HTTP/2-3, HTML parse, preload scanner, CSSOMDOM → render tree → layout → paint → composite; JS blocks parsing unless async/defer/module. 2. Make a marketing page score 95 on Lighthouse. Self-host/subset fonts with font-display, next/image, lazy below-the-fold video (preload\"none\"/IntersectionObserver), avoid layout shift, defer third-party scripts, cache headers (see next.config.js). 3. Build smooth inertia scrolling without hijacking everything. Move a target on wheel/keys, ease real scrollTop with rAF lerp, step aside for inner scrollers, fixed overlays, dialogs, touch, reduced motion. Here: useInertiaScroll. 4. CSP, CORS and security headers. Know what each blocks; why Permissions-Policy: microphone(self) is needed for voice search; trade-offs of inline styles with CSP. 5. Hydration & streaming deep dive. Suspense boundaries stream HTML; selective hydration prioritises interacted regions; why browser-only reads belong in effects. 6. Migrate a large CSS codebase safely. Codemods, visual regression tests, strangler approach, tokenise colours first."},{"slug":"interview--04-dsa","title":"04 · Data Structures & Algorithms","folder":"interview","heading":"04 · Data Structures & Algorithms","id":"","text":""},{"slug":"interview--04-dsa","title":"04 · Data Structures & Algorithms","folder":"interview","heading":"04 · Data Structures & Algorithms","id":"","text":"Target pace at this level: Easy ≤ 10 min, Medium ≤ 25 min, Hard ≤ 40 min, always stating complexity and edge cases. Pattern > problem count."},{"slug":"interview--04-dsa","title":"04 · Data Structures & Algorithms","folder":"interview","heading":"Easy","id":"easy","text":"Problem Pattern Key idea Two Sum Hash map store value→index, one pass, O(n) Valid Parentheses Stack push open, match on close Merge Two Sorted Lists Two pointers dummy head Best Time to Buy/Sell Stock Running min one pass Binary Search Binary search lo<hi, avoid overflow Reverse Linked List Pointers prev/curr/next Valid Anagram / Palindrome Counting / two pointers Maximum Depth of Binary Tree DFS recursion"},{"slug":"interview--04-dsa","title":"04 · Data Structures & Algorithms","folder":"interview","heading":"Medium","id":"medium","text":"Problem Pattern Key idea Longest Substring Without Repeating Sliding window map char→last index 3Sum Sort two pointers skip duplicates Group Anagrams Hashing sorted key / count tuple Top K Frequent Elements Heap / bucket O(n log k) or O(n) Number of Islands BFS/DFS / DSU grid flood fill Course Schedule Topological sort Kahn's / DFS colours LRU Cache Hash map doubly linked list O(1) get/put Merge Intervals Sort sweep Kth Largest in Array Quickselect / heap avg O(n) Coin Change 1-D DP dp[a]min(dp[a-c]1) Word Break DP trie/set Lowest Common Ancestor Tree recursion Rotting Oranges Multi-source BFS"},{"slug":"interview--04-dsa","title":"04 · Data Structures & Algorithms","folder":"interview","heading":"Hard","id":"hard","text":"Problem Pattern Key idea Median of Two Sorted Arrays Binary search on partition O(log min(m,n)) Trapping Rain Water Two pointers / monotonic stack Sliding Window Maximum Monotonic deque O(n) Merge K Sorted Lists Heap O(N log k) Word Ladder BFS (bidirectional) Edit Distance 2-D DP Longest Increasing Subsequence DP patience sort O(n log n) Serialize/Deserialize Binary Tree Preorder markers Alien Dictionary Graph topo sort Minimum Window Substring Sliding window counts Dijkstra / Network Delay Time Heap graph Design a Text Editor / Autocomplete Trie heap"},{"slug":"interview--04-dsa","title":"04 · Data Structures & Algorithms","folder":"interview","heading":"Project-flavoured problems (talk about these from real code)","id":"project-flavoured-problems-talk-about-these-from-real-code","text":"Tokenizer (lib/editor/code/Tokenizer.ts): a spec-driven lexer whose tokens concatenate back to the source — prove it with a property test (join(tokens) source). Code formatter (formatCode.ts): bracket-depth indentation with a stack of per-line open counts; idempotent (format(format(x)) format(x)) and never touches strings/comments. Sliding window / interpolation: easeToward is an exponential lerp: x (target-x) (1 - e^(-k·dt)) — frame-rate independent. Reading time & WPM: wpmFromElapsed(words, ms); edge cases: zero elapsed, finishing early, clamping."},{"slug":"interview--04-dsa","title":"04 · Data Structures & Algorithms","folder":"interview","heading":"Complexity cheat-sheet","id":"complexity-cheat-sheet","text":"Array access O(1) · hash avg O(1) · balanced BST O(log n) · heap push/pop O(log n) · sort O(n log n) · BFS/DFS O(VE) · Dijkstra O((VE) log V)."},{"slug":"interview--05-system-design","title":"05 · System Design","folder":"interview","heading":"05 · System Design","id":"","text":""},{"slug":"interview--05-system-design","title":"05 · System Design","folder":"interview","heading":"05 · System Design","id":"","text":"Framework (use every time): requirements → estimates → API → data model → high-level design → deep dives → bottlenecks/failure modes → trade-offs."},{"slug":"interview--05-system-design","title":"05 · System Design","folder":"interview","heading":"Easy (components and vocabulary)","id":"easy-components-and-vocabulary","text":"1. Load balancer? Spreads traffic (L4/L7), health-checks, enables rolling deploys. 2. Cache — where and why? Browser, CDN, app (Redis), DB buffer. Cuts latency/load; costs staleness. 3. SQL vs NoSQL? Relations/transactions vs flexible schema/horizontal scale; choose by access patterns. 4. What is a CDN? Edge cache for static assets and videos (this project's landing video). 5. Horizontal vs vertical scaling?"},{"slug":"interview--05-system-design","title":"05 · System Design","folder":"interview","heading":"Medium","id":"medium","text":"1. Design a URL shortener. Base62 of a counter/ID service; read-heavy → cache; 301 vs 302; abuse limits. 2. Design a rate limiter. Token bucket in Redis (atomic Lua), per-user/IP keys, headers Retry-After; distributed clock caveats. 3. Design a notification system. Producer → queue (Kafka/SQS) → workers per channel; idempotency keys; retries with backoff DLQ; user preferences. 4. Design this Speed Reader platform. Stories (CRUD, tags, thumbnails), per-user sessions/history, quizzes, comments/likes. Postgres Prisma, object storage (S3) for PDFs/images, CDN, Redis for hot lists, search via Postgres FTS → OpenSearch later. Frontend: Next.js; session isolation per user (SessionBoundary remounts on user change). 5. Pagination. Offset vs keyset (cursor); why keyset scales and stays stable under inserts. 6. Design a comment system with replies/likes. Adjacency list depth, denormalised counters with async reconciliation."},{"slug":"interview--05-system-design","title":"05 · System Design","folder":"interview","heading":"Hard","id":"hard","text":"1. Design Google Docs / collaborative editor. OT vs CRDT; operation log, presence, cursors, offline merge, snapshots compaction, permissions; WebSocket fan-out by document shard. (Relevant to \"teams and shared notes\" on this roadmap.) 2. Design YouTube/Netflix streaming. Upload → transcode ladder (HLS/DASH) → segments on object store → CDN; adaptive bitrate; recommendation as a separate pipeline. 3. Design a ride-dispatch system (your DispatchHub project). Geo-index (H3/geohash), matching with batching windows, supply/demand surge, at-least-once events with idempotent consumers. 4. Design a global feed ranking. Candidate generation → ranking → re-ranking; fan-out on write vs read; hot-key (celebrity) handling. 5. Design a payments system. Idempotency keys, double-entry ledger, sagas, reconciliation, exactly-once effects via outbox. 6. Multi-region active-active. Conflict resolution, data residency, failover drills, consistency levels (PACELC)."},{"slug":"interview--05-system-design","title":"05 · System Design","folder":"interview","heading":"Cross-cutting talking points","id":"cross-cutting-talking-points","text":"CAP/PACELC, consistency models, idempotency, backpressure, circuit breakers, observability (RED/USE metrics, tracing), SLOs and error budgets, capacity maths (QPS DAU × actions / 86 400, ×3–5 for peak)."},{"slug":"interview--06-backend-apis-databases","title":"06 · Backend, APIs & Databases","folder":"interview","heading":"06 · Backend, APIs & Databases","id":"","text":""},{"slug":"interview--06-backend-apis-databases","title":"06 · Backend, APIs & Databases","folder":"interview","heading":"06 · Backend, APIs & Databases","id":"","text":""},{"slug":"interview--06-backend-apis-databases","title":"06 · Backend, APIs & Databases","folder":"interview","heading":"Easy","id":"easy","text":"1. REST verbs/status codes? GET/POST/PUT/PATCH/DELETE; 200/201/204, 400/401/403/404/409/422, 429, 500/503. 2. PUT vs PATCH? Idempotency? PUT replaces (idempotent); PATCH partial (may not be). 3. Primary key vs foreign key vs unique? 4. SQL joins. INNER, LEFT, RIGHT, FULL; know what each returns on missing matches. 5. What is middleware in Express? Functions in the request pipeline: parse, auth, validate, error handler last."},{"slug":"interview--06-backend-apis-databases","title":"06 · Backend, APIs & Databases","folder":"interview","heading":"Medium","id":"medium","text":"1. Index design. B-tree on filtersort columns; composite order equality first, then range/sort; covering indexes; cost on writes. Read EXPLAIN ANALYZE. 2. Transactions & isolation. ACID; read committed vs repeatable read vs serializable; phantom reads; lost update → SELECT … FOR UPDATE or optimistic version column. 3. N1 queries. Prisma include/select, IN batching, DataLoader. 4. Validation & error handling. Schema-validate at the edge (Zod), map domain errors to codes, never leak stack traces, central error middleware. 5. Pagination & filtering API. Cursor tokens, stable sort keys, max page size. 6. File uploads. Presigned URLs straight to object storage; validate type/size; scan; thumbnails async. Here: thumbnails are validated/sanitised by safeThumbnail on the client; the backend must re-validate. 7. Migrations. Expand → migrate → contract; never drop a column in the same release that stops using it."},{"slug":"interview--06-backend-apis-databases","title":"06 · Backend, APIs & Databases","folder":"interview","heading":"Hard","id":"hard","text":"1. Zero-downtime schema change on a 500M-row table. Online DDL, shadow table dual writes backfill cutover, feature flags. 2. Distributed transaction without 2PC. Saga (choreography vs orchestration), outbox pattern, idempotent consumers. 3. Exactly-once? Impossible end-to-end; at-least-once idempotency keys dedupe tables. 4. Caching strategies & invalidation. Cache-aside, write-through, stampede protection (single-flight, jittered TTL), versioned keys. 5. Hot-row contention / counters. Sharded counters, Redis INCR periodic flush, CRDT counters. 6. Query tuning case. Slow ORDER BY createdat LIMIT 20 with a filter: composite index (userid, createdat DESC), avoid OFFSET, check plan for sort node. 7. Node performance. Event loop blocking (CPU work → worker threads), streaming big responses, connection pooling (PgBouncer), graceful shutdown (SIGTERM drain)."},{"slug":"interview--07-auth-security","title":"07 · Auth & Security","folder":"interview","heading":"07 · Auth & Security","id":"","text":""},{"slug":"interview--07-auth-security","title":"07 · Auth & Security","folder":"interview","heading":"07 · Auth & Security","id":"","text":""},{"slug":"interview--07-auth-security","title":"07 · Auth & Security","folder":"interview","heading":"Easy","id":"easy","text":"1. Authentication vs authorisation? 2. Hashing vs encryption? Hashing is one-way (use bcrypt/argon2 with salt); encryption is reversible. 3. What is XSS / CSRF / SQL injection? Script injection into pages / forged cross-site requests using the user's cookies / unsanitised input in queries (use parameterised queries). 4. HTTPS why? Confidentiality, integrity, server authentication."},{"slug":"interview--07-auth-security","title":"07 · Auth & Security","folder":"interview","heading":"Medium","id":"medium","text":"1. Session cookies vs JWT. Cookies (HttpOnly, Secure, SameSite) server session easy revocation; JWT stateless but hard to revoke → short-lived access token rotating refresh token. 2. Refresh-token rotation & reuse detection. Issue new refresh on use, invalidate old; if an old one reappears, revoke the whole family. 3. OAuth 2.0 / OIDC (Google, Apple, Facebook). Authorization Code PKCE; validate state, nonce, ID-token signature/audience; link accounts by verified email. 4. OTP login. Hash OTPs, short TTL, attempt limits, per-identity per-IP rate limits, constant-time compare. 5. Sanitising rich text. Allow-list sanitiser, never dangerouslySetInnerHTML unsanitised. Here: the editor has its own sanitiser and safeThumbnail blocks non-image data URLs. 6. Per-user data isolation on the client. Here: lib/session namespaces storage per user and SessionBoundary remounts the tree on user change, tested in test:session."},{"slug":"interview--07-auth-security","title":"07 · Auth & Security","folder":"interview","heading":"Hard","id":"hard","text":"1. Threat-model a login file-upload service (STRIDE). Brute force, credential stuffing, token theft, SSRF via URL fetch, zip bombs, content-type confusion, path traversal. 2. Design secure password reset. Single-use hashed tokens, expiry, no user enumeration, invalidate sessions after reset. 3. Where do you store tokens in an SPA? Memory HttpOnly refresh cookie beats localStorage (XSS-readable). Discuss BFF pattern. 4. CSP design. Nonce-based script-src, frame-ancestors, report-only rollout. 5. Supply-chain security. Lockfiles, npm ci, provenance, Dependabot, pin CI actions, least-privilege tokens. 6. Secrets management & rotation. Vault/KMS, no secrets in the repo (.gitignore excludes .env), short-lived credentials."},{"slug":"interview--08-testing-deployment","title":"08 · Testing, CI/CD & Deployment","folder":"interview","heading":"08 · Testing, CI/CD & Deployment","id":"","text":""},{"slug":"interview--08-testing-deployment","title":"08 · Testing, CI/CD & Deployment","folder":"interview","heading":"08 · Testing, CI/CD & Deployment","id":"","text":""},{"slug":"interview--08-testing-deployment","title":"08 · Testing, CI/CD & Deployment","folder":"interview","heading":"Easy","id":"easy","text":"1. Unit vs integration vs e2e? Many fast unit tests, fewer integration, few e2e (test pyramid). 2. What makes a test good? Deterministic, isolated, fast, tests behaviour not implementation. 3. What is CI/CD?"},{"slug":"interview--08-testing-deployment","title":"08 · Testing, CI/CD & Deployment","folder":"interview","heading":"Medium","id":"medium","text":"1. How is this repo tested? npm run test:editor (55 tests: tokenizer, formatter idempotency, sanitiser, reading-mode clock) and npm run test:session (21 tests: per-user isolation). Run with npm test. 2. Property-based / invariant tests. Tokens re-concatenate to source; formatter is idempotent; wpm recalculation matches elapsed time. 3. Mocking strategy. Mock at boundaries (network, time), not internals; fake timers for debounce/rAF. 4. Environment config. Build-time NEXTPUBLIC vs runtime server env; one image, many environments requires runtime config for server values only. 5. Docker multi-stage builds. Deps → build → slim runtime, non-root user, healthcheck (see Dockerfile)."},{"slug":"interview--08-testing-deployment","title":"08 · Testing, CI/CD & Deployment","folder":"interview","heading":"Hard","id":"hard","text":"1. Zero-downtime deploys. Rolling/blue-green/canary, readiness probes, connection draining, backwards-compatible DB migrations. 2. Feature flags & safe rollout. Percentage rollouts, kill switch, cleanup debt. 3. Observability. Structured logs with request IDs, RED metrics, distributed tracing, frontend RUM (web-vitals), source maps in Sentry, alert on SLO burn rate not raw errors. 4. Rollback strategy. Immutable artefacts, DB expand/contract so N-1 still works, automated smoke test after deploy. 5. Testing flaky e2e. Network isolation, stable selectors (roles/labels), waiting on conditions not timeouts, quarantine owner. 6. Performance budget in CI. Lighthouse CI, bundle-size limits, fail the PR on regression."},{"slug":"interview--08-testing-deployment","title":"08 · Testing, CI/CD & Deployment","folder":"interview","heading":"Release checklist for this project","id":"release-checklist-for-this-project","text":"npm ci → npm run typecheck → npm test → npm run lint → npm run build → smoke npm start → verify /, /dashboard, /reader, /read load. See docs/DEPLOYMENT.md."},{"slug":"interview--09-behavioral-projects","title":"09 · Behavioral & Project Walkthrough","folder":"interview","heading":"09 · Behavioral & Project Walkthrough","id":"","text":""},{"slug":"interview--09-behavioral-projects","title":"09 · Behavioral & Project Walkthrough","folder":"interview","heading":"09 · Behavioral & Project Walkthrough","id":"","text":"At this level, behavioral rounds can veto an otherwise strong loop. Use STAR, lead with the result, quantify, and show judgement under ambiguity."},{"slug":"interview--09-behavioral-projects","title":"09 · Behavioral & Project Walkthrough","folder":"interview","heading":"Easy","id":"easy","text":"1. Tell me about yourself (90 seconds: who you are → what you built → what you want next). 2. Why this company/role? 3. Your favourite project and why."},{"slug":"interview--09-behavioral-projects","title":"09 · Behavioral & Project Walkthrough","folder":"interview","heading":"Medium","id":"medium","text":"1. Walk through Speed Reader end to end. Problem (people read slowly and retain little) → solution (timed reader quiz analytics) → architecture (Next.js 14, per-user session layer, dependency-free rich editor, Express/Prisma backend) → hard problems → results. 2. Hardest technical problem. E.g. the code formatter: language-agnostic, idempotent, never alters strings/comments, handles collapsed single-line code; or inertia scrolling that yields to inner scrollers. 3. Disagreement with a teammate. Data first, disagree-and-commit, outcome. 4. A bug you shipped. Own it; root cause (e.g. footer painting over a fixed page); prevention (route-level guard test). 5. Prioritisation with deadlines (hackathons: DispatchHub, CredMatch)."},{"slug":"interview--09-behavioral-projects","title":"09 · Behavioral & Project Walkthrough","folder":"interview","heading":"Hard","id":"hard","text":"1. A time you changed direction mid-project. E.g. rolled back the paste-as-code change when it caused regressions; how you decided and communicated. 2. Led without authority / mentored. 3. Made a decision with incomplete data and it was wrong. 4. Ownership beyond scope (set up CI/Docker, docs, tests no one asked for). 5. Raise the bar: how you'd improve engineering quality on a team — review standards, tests, docs, on-call hygiene."},{"slug":"interview--09-behavioral-projects","title":"09 · Behavioral & Project Walkthrough","folder":"interview","heading":"Project talking points (be ready to go 3 levels deep)","id":"project-talking-points-be-ready-to-go-3-levels-deep","text":"Per-user isolation: namespaced storage remount boundary; tested adoption of legacy keys. Editor: own tokenizer/sanitiser/code widget; why not a library (bundle size, control), what you'd reconsider (CRDT collaboration). Reading mode: real-time clock independent of scroll, WPM recalculated on early finish, rail of ≤5 ticks. Trade-offs you accepted: localStorage-first persistence, backend optional (NEXTPUBLICAPIURL empty standalone). What you'd do next: real teams/shared docs (OT/CRDT), server-side search, e2e tests, a11y audit."},{"slug":"interview--10-study-plan","title":"10 · 8-Week Study Plan & Level Rubric","folder":"interview","heading":"10 · 8-Week Study Plan & Level Rubric","id":"","text":""},{"slug":"interview--10-study-plan","title":"10 · 8-Week Study Plan & Level Rubric","folder":"interview","heading":"10 · 8-Week Study Plan & Level Rubric","id":"","text":"Week Focus Output 1 JS/TS internals, event loop, async 30 JS questions 5 utility implementations 2 DSA: arrays, hashing, two pointers, sliding window, stack 40 problems (15 E / 20 M / 5 H) 3 DSA: trees, graphs, heaps, binary search 40 problems 4 DSA: DP, backtracking, tries mock interview ×2 30 problems 5 React Next.js deep dive, perf, a11y Build/profile one feature, write a perf note 6 System design ×6 (shortener, rate limiter, notifications, feed, chat, docs) One-page design each 7 Backend/DB/security, deployment Write an ADR for this project's deploy 8 Behavioral stories, mocks, revise weak spots 8 STAR stories; 3 full mock loops"},{"slug":"interview--10-study-plan","title":"10 · 8-Week Study Plan & Level Rubric","folder":"interview","heading":"Daily rhythm","id":"daily-rhythm","text":"60–90 min DSA · 30 min fundamentals · 30 min design reading · 15 min recall of yesterday's mistakes."},{"slug":"interview--10-study-plan","title":"10 · 8-Week Study Plan & Level Rubric","folder":"interview","heading":"How levels are judged (typical)","id":"how-levels-are-judged-typical","text":"Easy questions: must be fast and flawless; hesitation here costs the offer. Medium: clean solution, correct complexity, tests edge cases unprompted. Hard / design: structure, trade-offs, failure modes, and clear communication; a partially optimal solution well explained beats a silent perfect one. Senior signal: you ask clarifying questions, quantify, choose boring technology on purpose, and say what you would monitor."},{"slug":"interview--11-this-release","title":"11 — Ownership, routing & profile photos (Easy / Medium / Hard)","folder":"interview","heading":"11 — Ownership, routing & profile photos (Easy / Medium / Hard)","id":"","text":""},{"slug":"interview--11-this-release","title":"11 — Ownership, routing & profile photos (Easy / Medium / Hard)","folder":"interview","heading":"11 — Ownership, routing & profile photos (Easy / Medium / Hard)","id":"","text":"Questions an interviewer at the ₹2.5 Cr band could ask about this change set. Cover the answer first."},{"slug":"interview--11-this-release","title":"11 — Ownership, routing & profile photos (Easy / Medium / Hard)","folder":"interview","heading":"Easy","id":"easy","text":"1. Why a routes.ts constant instead of string literals? One place to change/grep, typed helpers (story(id)), no dead links. 2. Why /story/[id] rather than state-only? Refresh, share and back-button work; the URL is the source of truth. 3. Why downscale an avatar before storing? localStorage is 5 MB and synchronous; 256px JPEG ≈ 15 KB."},{"slug":"interview--11-this-release","title":"11 — Ownership, routing & profile photos (Easy / Medium / Hard)","folder":"interview","heading":"Medium","id":"medium","text":"4. A user saw someone else as the \"owner\" of their upload — root cause? Authorship was a hash of the content id. Fix: derive it from where the data lives (the uploader's library) with the hash only as a fallback for built-ins. 5. Why inject the owner resolver? contentMeta ← store ← session: importing session from contentMeta creates a cycle. Dependency inversion keeps modules acyclic and testable. 6. Edit modal reuse — trade-offs? Shared form parts remove drift; the cost is coupling both modals to one layout. Keep parts presentational. 7. Validate image uploads how? MIME size check client-side, re-encode through canvas (strips payloads), render only data URLs matching our own format (safeAvatar)."},{"slug":"interview--11-this-release","title":"11 — Ownership, routing & profile photos (Easy / Medium / Hard)","folder":"interview","heading":"Hard","id":"hard","text":"8. Move this to production — what changes? authorId becomes a DB foreign key set server-side from the session (never client-supplied); avatars go to object storage CDN with signed uploads; authorization checked on every mutation. 9. IDOR on edit/delete? Client gating (isCustomStory) is UX only; the API must verify story.ownerId session.userId. 10. Two tabs edit the same story — what happens? Last write wins today; fix with a version/ETag and optimistic concurrency (409 → merge UI). 11. Orphaned media (cover videos in IndexedDB)? Delete on replace/delete only after the save commits; a periodic sweep removes refs no story holds."},{"slug":"interview--readme","title":"SDE Interview Prep — topic-wise (Easy / Medium / Hard)","folder":"interview","heading":"SDE Interview Prep — topic-wise (Easy / Medium / Hard)","id":"","text":""},{"slug":"interview--readme","title":"SDE Interview Prep — topic-wise (Easy / Medium / Hard)","folder":"interview","heading":"SDE Interview Prep — topic-wise (Easy / Medium / Hard)","id":"","text":"Aimed at top-paying SDE roles (the ₹2.5 Cr band: Staff-leaning SDE-2/SDE-3 at product and big-tech companies). At that level the bar is: sound fundamentals, clean problem solving, and the ability to design and defend real systems. Every topic below has Easy → Medium → Hard questions with short model answers, and ties back to code in this project so you can speak from experience. # Topic Why it matters at this level 01 JavaScript & TypeScript Every frontend/full-stack loop starts here 02 React Rendering model, state, performance 03 Next.js & Web Platform SSR/CSR, routing, caching, CSS pitfalls, Core Web Vitals 04 Data Structures & Algorithms The gate for every top-tier loop 05 System Design Deciding factor for level and pay 06 Backend, APIs & Databases Express/Prisma, SQL, indexing, transactions 07 Auth & Security Sessions, JWT, OAuth, OWASP 08 Testing, CI/CD & Deployment Production ownership 09 Behavioral & Project Walkthrough Leadership principles, impact, depth in your own work 11 This release: ownership, routing, photos Defending real design decisions 10 Study Plan 8-week schedule and how the levels are scored How to use: cover the answer, say yours out loud, then compare. For every Medium/Hard question, also state the trade-off and the failure mode — that is what separates senior answers from mid-level ones."},{"slug":"research--01-scaling-security-and-notifier","title":"Scaling, security and the test notifier","folder":"research","heading":"Scaling, security and the test notifier","id":"","text":""},{"slug":"research--01-scaling-security-and-notifier","title":"Scaling, security and the test notifier","folder":"research","heading":"Scaling, security and the test notifier","id":"","text":""},{"slug":"research--01-scaling-security-and-notifier","title":"Scaling, security and the test notifier","folder":"research","heading":"Question","id":"question","text":"What would it take to run Pacewise with a real backend at large scale, safely, and how should the \"take a test / revise\" reminder work?"},{"slug":"research--01-scaling-security-and-notifier","title":"Scaling, security and the test notifier","folder":"research","heading":"Findings","id":"findings","text":"State must leave the browser. Today progress, sessions and stories live in localStorage; a backend needs one source of truth per user, behind an API. Reads dominate. Story pages and notes are read far more than written, so they suit a CDN plus a cache; user progress is write-heavy and suits a database with per-user partitioning. Security basics that cost little and prevent most incidents: hashed passwords, short-lived tokens, per-user authorisation on every query, rate limits on login and upload, and input validation on every boundary. Uploads (PDFs) go straight to object storage with a signed URL; the server stores only metadata and the owner id. Monitoring: structured logs, request-level metrics (latency, errors), and alerts on error rate rather than on single failures."},{"slug":"research--01-scaling-security-and-notifier","title":"Scaling, security and the test notifier","folder":"research","heading":"Notifier algorithm","id":"notifier-algorithm","text":"Use spaced repetition: after each test, schedule the next review at an interval that grows when the score is good and shrinks when it is poor. Score Next review Below 50% next day 50–80% in 3 days Above 80% in 7 days, then double each time A scheduler job picks users whose next-review time has passed and sends one reminder per user, never more than one a day."},{"slug":"research--01-scaling-security-and-notifier","title":"Scaling, security and the test notifier","folder":"research","heading":"Decision","id":"decision","text":"Keep the current client-side design for now; when adding a backend, move state first, then uploads, then reminders."},{"slug":"research--02-uploaded-pdf-ownership-bug","title":"Uploaded PDF showed the wrong owner","folder":"research","heading":"Uploaded PDF showed the wrong owner","id":"","text":""},{"slug":"research--02-uploaded-pdf-ownership-bug","title":"Uploaded PDF showed the wrong owner","folder":"research","heading":"Uploaded PDF showed the wrong owner","id":"","text":""},{"slug":"research--02-uploaded-pdf-ownership-bug","title":"Uploaded PDF showed the wrong owner","folder":"research","heading":"Question","id":"question","text":"A PDF uploaded by one person appeared to belong to someone else. Why?"},{"slug":"research--02-uploaded-pdf-ownership-bug","title":"Uploaded PDF showed the wrong owner","folder":"research","heading":"Findings","id":"findings","text":"Large PDFs exceed the browser's localStorage quota, so the save failed silently. The record saying \"this story belongs to user X\" was written in the same step, so it was lost too. With no owner on record, the app fell back to whoever was signed in."},{"slug":"research--02-uploaded-pdf-ownership-bug","title":"Uploaded PDF showed the wrong owner","folder":"research","heading":"Fix","id":"fix","text":"Ownership is now kept in a separate small list (customStoryClaims) that always fits. SessionManager.findCustomStoryOwner checks that list before trusting anything else. A test covers the oversized-PDF case."},{"slug":"research--02-uploaded-pdf-ownership-bug","title":"Uploaded PDF showed the wrong owner","folder":"research","heading":"Decision","id":"decision","text":"Never store ownership in the same write as large content."},{"slug":"research--03-vercel-deployments-vs-domains","title":"Vercel deployments versus the domain","folder":"research","heading":"Vercel deployments versus the domain","id":"","text":""},{"slug":"research--03-vercel-deployments-vs-domains","title":"Vercel deployments versus the domain","folder":"research","heading":"Vercel deployments versus the domain","id":"","text":""},{"slug":"research--03-vercel-deployments-vs-domains","title":"Vercel deployments versus the domain","folder":"research","heading":"Question","id":"question","text":"Why did a specific deployment URL not show the update while the main domain did?"},{"slug":"research--03-vercel-deployments-vs-domains","title":"Vercel deployments versus the domain","folder":"research","heading":"Findings","id":"findings","text":"Every deploy gets its own permanent URL (like pacewise-xxxx.vercel.app) showing exactly that build. The production domain always points at the latest production deployment. A deployment can be Ready but not promoted, or built from a branch, so its URL and the domain can differ. Deployment URLs may also be protected by Vercel authentication, so they can look \"not available\" to visitors."},{"slug":"research--03-vercel-deployments-vs-domains","title":"Vercel deployments versus the domain","folder":"research","heading":"Decision","id":"decision","text":"Share the production domain (and use it in the QR code); treat deployment URLs as per-build previews."},{"slug":"research--readme","title":"Research","folder":"research","heading":"Research","id":"","text":""},{"slug":"research--readme","title":"Research","folder":"research","heading":"Research","id":"","text":"Findings from investigating the questions behind Pacewise: what it takes to scale it, why a bug happened, and how deployment really works. Each note states the question, what was found, and the decision taken. Scaling, security and the test notifier Uploaded PDF showed the wrong owner Vercel deployment URL versus the domain Every note ends with the decision, so you can read just the last section when short on time."}];
